/* DAWAH X — ahmad, অধ্যায় 127 · খণ্ড 127 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][127]=[[25201,25201,"","","‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّهَا كَانَتْ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلَانِ مِنْ إِنَاءٍ وَاحِدٍ كِلَاهُمَا يَغْتَرِفُ مِنْهُ ‏","","",""],[25202,25202,"","","‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنِي ‏ ‏عَامِرُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ خَبُثَتْ نَفْسِي وَلَكِنْ لِيَقُلْ ‏ ‏لَقِسَتْ ‏ ‏نَفْسِي ‏","","",""],[25203,25203,"","","‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سَتَرَتْ عَلَى بَابِهَا ‏ ‏دُرْنُوكًا ‏ ‏فِيهِ خَيْلٌ ‏ ‏أُولَاتُ ‏ ‏أَجْنِحَةٍ فَقَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سَفَرٍ ‏ ‏فَأَمَرَهَا فَنَزَعَتْهُ ‏","","",""],[25204,25204,"","","‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اعْتَكَفَ ‏ ‏لَمْ يَخْرُجْ مِنْ الْمَسْجِدِ إِلَّا لِحَاجَةِ الْإِنْسَانِ ‏","","",""],[25205,25205,"","","‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُ بَلَغَهَا أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَيِّتُ يُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ فَقَالَتْ يَرْحَمُ اللَّهُ ‏ ‏عُمَرَ ‏ ‏وَابْنَ عُمَرَ ‏ ‏فَوَاللَّهِ مَا هُمَا بِكَاذِبَيْنِ وَلَا مُكَذَّبَيْنِ وَلَا مُتَزَيِّدَيْنِ إِنَّمَا قَالَ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجُلٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏وَمَرَّ بِأَهْلِهِ وَهُمْ يَبْكُونَ عَلَيْهِ فَقَالَ إِنَّهُمْ لَيَبْكُونَ عَلَيْهِ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَيُعَذِّبُهُ فِي قَبْرِهِ ‏","","",""],[25206,25206,"","","‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مُحَمَّدٍ الْوَرَّاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَائِلُ بْنُ دَاوُدَ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْدَ بْنَ حَارِثَةَ ‏ ‏فِي جَيْشٍ قَطُّ إِلَّا ‏ ‏أَمَّرَهُ عَلَيْهِمْ وَلَوْ بَقِيَ بَعْدَهُ لَاسْتَخْلَفَهُ ‏","","",""],[25207,25207,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ ‏ ‏تُحِدَّ ‏ ‏فَوْقَ ثَلَاثَةِ أَيَّامٍ إِلَّا عَلَى زَوْجِهَا ‏","","",""],[25208,25208,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏ ‏هَذَا آخِرُ مُسْنَدِ السَّيِّدَةِ ‏ ‏عَائِشَةَ ‏","","",""],[25209,25209,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنِ ‏ ‏الْفِرَاسِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَقْبَلَتْ ‏ ‏فَاطِمَةُ ‏ ‏تَمْشِي كَأَنَّ مِشْيَتَهَا مِشْيَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَرْحَبًا بِابْنَتِي ثُمَّ أَجْلَسَهَا عَنْ يَمِينِهِ ‏ ‏أَوْ عَنْ شِمَالِهِ ‏ ‏ثُمَّ إِنَّهُ أَسَرَّ إِلَيْهَا حَدِيثًا فَبَكَتْ فَقُلْتُ لَهَا اسْتَخَصَّكِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثَهُ ثُمَّ تَبْكِينَ ثُمَّ إِنَّهُ أَسَرَّ إِلَيْهَا حَدِيثًا فَضَحِكَتْ فَقُلْتُ مَا رَأَيْتُ كَالْيَوْمِ فَرَحًا أَقْرَبَ مِنْ حُزْنٍ فَسَأَلْتُهَا عَمَّا قَالَ فَقَالَتْ مَا كُنْتُ لِأُفْشِيَ سِرَّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا ‏ ‏قُبِضَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلْتُهَا فَقَالَتْ إِنَّهُ أَسَرَّ إِلَيَّ فَقَالَ ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏كَانَ يُعَارِضُنِي بِالْقُرْآنِ فِي كُلِّ عَامٍ مَرَّةً وَإِنَّهُ عَارَضَنِي بِهِ الْعَامَ مَرَّتَيْنِ وَلَا أُرَاهُ إِلَّا قَدْ حَضَرَ أَجَلِي وَإِنَّكِ أَوَّلُ أَهْلِ بَيْتِي لُحُوقًا بِي وَنِعْمَ ‏ ‏السَّلَفُ ‏ ‏أَنَا لَكِ فَبَكَيْتُ لِذَلِكَ ثُمَّ قَالَ أَلَا تَرْضَيْنَ أَنْ تَكُونِي سَيِّدَةَ نِسَاءِ هَذِهِ الْأُمَّةِ ‏ ‏أَوْ نِسَاءِ الْمُؤْمِنِينَ ‏ ‏قَالَتْ فَضَحِكْتُ لِذَلِكَ ‏","","",""],[25210,25210,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا مَرِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا ابْنَتَهُ ‏ ‏فَاطِمَةَ ‏ ‏فَسَارَّهَا فَبَكَتْ ثُمَّ سَارَّهَا فَضَحِكَتْ فَسَأَلْتُهَا عَنْ ذَلِكَ فَقَالَتْ ‏ ‏أَمَّا حَيْثُ بَكَيْتُ فَإِنَّهُ أَخْبَرَنِي أَنَّهُ مَيِّتٌ فَبَكَيْتُ ثُمَّ أَخْبَرَنِي أَنِّي أَوَّلُ ‏ ‏أَهْلِهِ ‏ ‏لُحُوقًا بِهِ فَضَحِكْتُ ‏","","",""],[25211,25211,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أُمِّ سُلَيْمَانَ ‏ ‏وَكِلَاهُمَا كَانَ ثِقَةً ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُهَا عَنْ لُحُومِ الْأَضَاحِيِّ فَقَالَتْ قَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهَا ثُمَّ رَخَّصَ فِيهَا قَدِمَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏مِنْ سَفَرٍ فَأَتَتْهُ ‏ ‏فَاطِمَةُ ‏ ‏بِلَحْمٍ مِنْ ضَحَايَاهَا فَقَالَ أَوَلَمْ يَنْهَ عَنْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنَّهُ قَدْ رَخَّصَ فِيهَا قَالَتْ فَدَخَلَ ‏ ‏عَلِيٌّ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ ذَلِكَ فَقَالَ لَهُ ‏ ‏كُلْهَا مِنْ ذِي الْحِجَّةِ إِلَى ذِي الْحِجَّةِ ‏","","",""],[25212,25212,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَسَنٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏فَاطِمَةَ ابْنَةِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهَا ‏ ‏فَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْمَسْجِدَ صَلَّى عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَسَلَّمَ وَقَالَ اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ وَإِذَا خَرَجَ صَلَّى عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَسَلَّمَ ثُمَّ قَالَ اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَافْتَحْ لِي أَبْوَابَ فَضْلِكَ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏فَلَقِيتُ ‏ ‏عَبْدَ اللَّهِ بْنَ حَسَنٍ ‏ ‏فَسَأَلْتُهُ عَنْ هَذَا الْحَدِيثِ فَقَالَ ‏ ‏كَانَ إِذَا دَخَلَ قَالَ ‏ ‏رَبِّ افْتَحْ لِي بَابَ رَحْمَتِكَ وَإِذَا خَرَجَ قَالَ رَبِّ افْتَحْ لِي بَابَ فَضْلِكَ ‏","","",""],[25213,25213,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَسَنِ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهَا ‏ ‏فَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْمَسْجِدَ قَالَ ‏ ‏بِسْمِ اللَّهِ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ وَإِذَا خَرَجَ قَالَ بِسْمِ اللَّهِ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَافْتَحْ لِي أَبْوَابَ فَضْلِكَ ‏","","",""],[25214,25214,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ الْحَسَنِ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَكَلَ ‏ ‏عَرْقًا ‏ ‏فَجَاءَ ‏ ‏بِلَالٌ ‏ ‏بِالْأَذَانِ فَقَامَ لِيُصَلِّيَ فَأَخَذْتُ بِثَوْبِهِ فَقُلْتُ يَا ‏ ‏أَبَهْ أَلَا تَتَوَضَّأُ فَقَالَ ‏ ‏مِمَّ أَتَوَضَّأُ يَا بُنَيَّةُ فَقُلْتُ مِمَّا مَسَّتْ النَّارُ فَقَالَ لِي أَوَلَيْسَ أَطْيَبُ طَعَامِكُمْ مَا مَسَّتْهُ النَّارُ ‏","","",""],[25215,25215,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَسَنِ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ابْنَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏إِذَا دَخَلَ الْمَسْجِدَ صَلَّى عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَسَلَّمَ ثُمَّ قَالَ اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ وَإِذَا خَرَجَ صَلَّى عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَسَلَّمَ وَقَالَ اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَافْتَحْ لِي أَبْوَابَ فَضْلِكَ ‏","","",""],[25216,25216,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏قَالَ ‏ ‏دَخَلَتْ ‏ ‏فَاطِمَةُ ‏ ‏عَلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالَتْ أَخْبَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي أَوَّلُ أَهْلِهِ لُحُوقًا بِهِ ‏","","",""],[25217,25217,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏قَالَ قَالَ ‏ ‏لَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيٍّ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏أَنْ أَنْسَخَ إِلَيْهِ وَصِيَّةَ ‏ ‏فَاطِمَةَ ‏ ‏فَكَانَ فِي وَصِيَّتِهَا ‏ ‏السِّتْرُ ‏ ‏الَّذِي يَزْعُمُ النَّاسُ أَنَّهَا أَحْدَثَتْهُ وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا فَلَمَّا رَآهُ رَجَعَ ‏","","",""],[25218,25218,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏فَاطِمَةُ ‏ ‏تَنْقُزُ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏وَتَقُولُ ‏ ‏بِأَبِي شَبَهُ النَّبِيِّ ‏ ‏لَيْسَ شَبِيهًا ‏ ‏بِعَلِيٍّ ‏","","",""],[25219,25219,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ وَحَدَّثَتْنِي ‏ ‏حَفْصَةُ ‏ ‏وَكَانَتْ سَاعَةٌ لَا يَدْخُلُ عَلَيْهِ فِيهَا أَحَدٌ أَنَّهُ كَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ حِينَ يَطْلُعُ الْفَجْرُ تَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيُنَادِي الْمُنَادِي بِالصَّلَاةِ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏أُرَاهُ قَالَ خَفِيفَتَيْنِ ‏","","",""],[25220,25220,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا شَأْنُ النَّاسِ ‏ ‏حَلُّوا ‏ ‏وَلَمْ تَحِلَّ مِنْ عُمْرَتِكَ قَالَ ‏ ‏إِنِّي ‏ ‏قَلَّدْتُ ‏ ‏هَدْيِي ‏ ‏وَلَبَّدْتُ ‏ ‏رَأْسِي فَلَا ‏ ‏أَحِلُّ ‏ ‏حَتَّى ‏ ‏أَحِلَّ ‏ ‏مِنْ الْحَجِّ ‏","","",""],[25221,25221,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَعَفَّانُ ‏ ‏وَيُونُسُ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏وَعُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ رَأَى ‏ ‏ابْنَ صَائِدٍ ‏ ‏فِي سِكَّةٍ مِنْ سِكَكِ ‏ ‏الْمَدِينَةِ ‏ ‏فَسَبَّهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَوَقَعَ فِيهِ فَانْتَفَخَ حَتَّى سَدَّ الطَّرِيقَ فَضَرَبَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏بِعَصًا كَانَتْ مَعَهُ حَتَّى كَسَّرَهَا عَلَيْهِ فَقَالَتْ لَهُ ‏ ‏حَفْصَةُ ‏ ‏مَا شَأْنُكَ وَشَأْنُهُ مَا يُولِعُكَ بِهِ أَمَا سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا يَخْرُجُ ‏ ‏الدَّجَّالُ ‏ ‏مِنْ غَضْبَةٍ يَغْضَبُهَا ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏عِنْدَ غَضْبَةٍ يَغْضَبُهَا ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏فِي حَدِيثِهِ مَا ‏ ‏تَوَالُعُكَ بِهِ ‏","","",""],[25222,25222,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏ابْنَ صَائِدٍ ‏ ‏مَرَّتَيْنِ فَأَمَّا مَرَّةً فَلَقِيتُهُ وَمَعَهُ بَعْضُ أَصْحَابِهِ فَقُلْتُ لِبَعْضِهِمْ نَشَدْتُكُمْ بِاللَّهِ إِنْ سَأَلْتُكُمْ عَنْ شَيْءٍ ‏ ‏لَتَصْدُقُنِّي قَالُوا نَعَمْ قَالَ قُلْتُ أَتُحَدِّثُونِي أَنَّهُ هُوَ قَالُوا لَا قُلْتُ كَذَبْتُمْ وَاللَّهِ لَقَدْ حَدَّثَنِي بَعْضُكُمْ وَهُوَ يَوْمَئِذٍ أَقَلُّكُمْ مَالًا وَوَلَدًا أَنَّهُ لَا يَمُوتُ حَتَّى يَكُونَ أَكْثَرَكُمْ مَالًا وَوَلَدًا وَهُوَ الْيَوْمَ كَذَلِكَ قَالَ فَحَدَّثَنَا ثُمَّ فَارَقْتُهُ ثُمَّ لَقِيتُهُ مَرَّةً أُخْرَى وَقَدْ تَغَيَّرَتْ عَيْنُهُ فَقُلْتُ مَتَى فَعَلَتْ عَيْنُكَ مَا أَرَى قَالَ لَا أَدْرِي قُلْتُ مَا تَدْرِي وَهِيَ فِي رَأْسِكَ فَقَالَ مَا تُرِيدُ مِنِّي يَا ‏ ‏ابْنَ عُمَرَ ‏ ‏إِنْ شَاءَ اللَّهُ تَعَالَى أَنْ يَخْلُقَهُ مِنْ عَصَاكَ هَذِهِ خَلَقَهُ ‏ ‏وَنَخَرَ ‏ ‏كَأَشَدِّ ‏ ‏نَخِيرِ ‏ ‏حِمَارٍ سَمِعْتُهُ قَطُّ فَزَعَمَ بَعْضُ أَصْحَابِي أَنِّي ضَرَبْتُهُ بِعَصًا كَانَتْ مَعِي حَتَّى ‏ ‏تَكَسَّرَتْ ‏ ‏وَأَمَّا أَنَا فَوَاللَّهِ مَا شَعَرْتُ فَدَخَلَ عَلَى أُخْتِهِ ‏ ‏حَفْصَةَ ‏ ‏فَأَخْبَرَهَا فَقَالَتْ مَا تُرِيدُ مِنْهُ أَمَا عَلِمْتَ أَنَّهُ قَالَ تَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَوَّلَ خُرُوجِهِ عَلَى النَّاسِ مِنْ غَضْبَةٍ يَغْضَبُهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏ابْنَ صَائِدٍ ‏ ‏مَرَّتَيْنِ فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ فَدَخَلْتُ عَلَى ‏ ‏حَفْصَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏فَأَخْبَرْتُهَا قَالَتْ مَا أَرَدْتَ إِلَيْهِ أَمَا عَلِمْتَ أَنَّهُ قَالَ إِنَّ أَوَّلَ خُرُوجِهِ عَلَى النَّاسِ غَضْبَةٌ يَغْضَبُهَا ‏","","",""],[25223,25223,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏مَرَّةً أُخْرَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏ابْنَ صَائِدٍ ‏ ‏مَرَّتَيْنِ فَأَمَّا مَرَّةً فَلَقِيتُهُ وَمَعَهُ أَصْحَابُهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏وَنَخَرَ ‏ ‏كَأَشَدِّ ‏ ‏نَخِيرِ ‏ ‏حِمَارٍ سَمِعْتُهُ قَالَ فَزَعَمَ أَصْحَابِي أَنِّي ضَرَبْتُهُ بِعَصًا كَانَتْ مَعِي حَتَّى انْكَسَرَتْ وَأَمَّا أَنَا فَلَمْ أَشْعُرْ بِذَلِكَ فَدَخَلْتُ عَلَى أُخْتِي ‏ ‏حَفْصَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏فَأَخْبَرْتُهَا بِذَلِكَ فَقَالَتْ وَمَا أَرَدْتَ إِلَيْهِ أَمَا عَلِمْتَ أَنَّهُ قَالَ ‏ ‏إِنَّ أَوَّلَ خُرُوجِهِ عَلَى النَّاسِ لِغَضْبَةٍ يَغْضَبُهَا ‏","","",""],[25224,25224,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏حَفْصَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا سَكَتَ الْمُؤَذِّنُ مِنْ الْأَذَانِ بِالصُّبْحِ وَبَدَا الصُّبْحُ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ تُقَامَ الصَّلَاةُ ‏","","",""],[25225,25225,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ الْخَطَّابِيُّ ‏ ‏فِي سَنَةِ ثَمَانٍ وَمِائَتَيْنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو الرَّقِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ يَعْنِي الْجَزَرِيَّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَذَّنَ الْمُؤَذِّنُ صَلَّى رَكْعَتَيْنِ وَحَرَّمَ الطَّعَامَ وَكَانَ لَا يُؤَذِّنُ حَتَّى يَطْلُعَ الْفَجْرُ ‏","","",""],[25226,25226,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏حَفْصَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ خَفِيفَتَيْنِ إِذَا بَدَا الْفَجْرُ ‏","","",""],[25227,25227,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَنَّهَا قَالَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَكَ لَمْ تَحِلَّ مِنْ عُمْرَتِكَ قَالَ ‏ ‏إِنِّي ‏ ‏لَبَّدْتُ ‏ ‏رَأْسِي ‏ ‏وَقَلَّدْتُ ‏ ‏هَدْيِي ‏ ‏فَلَا ‏ ‏أَحِلُّ ‏ ‏حَتَّى أَنْحَرَ ‏","","",""],[25228,25228,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏طَلَعَ ‏ ‏الْفَجْرُ ‏ ‏لَا ‏ ‏يُصَلِّي إِلَّا رَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[25229,25229,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ يَعْنِي الطَّالَقَانِيَّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏حَفْصَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ ‏ ‏خَفِيفَتَيْنِ بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الصُّبْحِ ‏","","",""],[25230,25230,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرٌ يَعْنِي ابْنَ بُرْقَانَ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏حَفْصَةَ ‏ ‏أَخْبَرَتْهُ قَالَتْ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏أَحِلَّ ‏ ‏فِي حَجَّتِهِ الَّتِي حَجَّ ‏ ‏و قَالَ ‏ ‏كَثِيرُ بْنُ مُرَّةَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏","","",""],[25231,25231,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ يَعْنِي ابْنَ أَبِي حَمْزَةَ ‏ ‏قَالَ قَالَ ‏ ‏نَافِعٌ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يَقُولُ أَخْبَرَتْنِي ‏ ‏حَفْصَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَزْوَاجَهُ أَنْ يَحْلِلْنَ عَامَ حَجَّةِ الْوَدَاعِ فَقَالَتْ لَهُ فُلَانَةُ فَمَا يَمْنَعُكَ أَنْ تَحِلَّ فَقَالَ إِنِّي ‏ ‏لَبَّدْتُ ‏ ‏رَأْسِي ‏ ‏وَقَلَّدْتُ ‏ ‏هَدْيِي ‏ ‏فَلَسْتُ ‏ ‏أَحِلُّ ‏ ‏حَتَّى أَنْحَرَ ‏ ‏هَدْيِي ‏","","",""],[25232,25232,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ عُمَرَ ‏ ‏قَالَتْ ‏ ‏لَمَّا ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ أَنْ يَحْلِلْنَ بِعُمْرَةٍ قُلْنَ فَمَا يَمْنَعُكَ يَا رَسُولَ اللَّهِ أَنْ تَحِلَّ مَعَنَا قَالَ إِنِّي قَدْ ‏ ‏أَهْدَيْتُ ‏ ‏وَلَبَّدْتُ ‏ ‏فَلَا ‏ ‏أَحِلُّ ‏ ‏حَتَّى أَنْحَرَ ‏ ‏هَدْيِي ‏ ‏وَقَالَ ‏ ‏يَعْقُوبُ ‏ ‏فِي كِتَابِ الْحَجِّ أَنْحَرَ هَدِيَّتِي ‏","","",""],[25233,25233,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَنْ الرَّكْعَتَيْنِ بَعْدَ الْفَجْرِ قَبْلَ الصُّبْحِ ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ عُمَرَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي رَكْعَتَيْ الْفَجْرِ قَبْلَ الصُّبْحِ فِي بَيْتِي يُخَفِّفُهُمَا جِدًّا ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يُخَفِّفُهُمَا كَذَلِكَ ‏","","",""],[25234,25234,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏زَيْدٍ يَعْنِي ابْنَ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَسَأَلَهُ رَجُلٌ عَمَّا يَقْتُلُ الْمُحْرِمُ مِنْ الدَّوَابِّ فَقَالَ حَدَّثَتْنِي إِحْدَى ‏ ‏النِّسْوَةِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقْتُلُ الْحُدَيَّا وَالْغُرَابَ وَالْكَلْبَ ‏ ‏الْعَقُورَ ‏ ‏وَالْفَأْرَةَ وَالْعَقْرَبَ ‏","","",""],[25235,25235,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُبَشِّرٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَرْجُو أَنْ لَا يَدْخُلَ النَّارَ إِنْ شَاءَ اللَّهُ أَحَدٌ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَالْحُدَيْبِيَةَ ‏ ‏قَالَتْ فَقُلْتُ أَلَيْسَ اللَّهُ عَزَّ وَجَلَّ يَقُولُ ‏ { ‏وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا ‏} ‏قَالَ فَسَمِعَتْهُ يَقُولُ ‏ { ‏ثُمَّ ‏ ‏نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا ‏ ‏جِثِيًّا ‏ }","","",""],[25236,25236,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا ‏ ‏قَالَتْ لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ‏ ‏سُبْحَتِهِ ‏ ‏جَالِسًا قَطُّ حَتَّى كَانَ قَبْلَ مَوْتِهِ بِعَامٍ ‏ ‏أَوْ بِعَامَيْنِ ‏ ‏فَكَانَ ‏ ‏يُصَلِّي فِي ‏ ‏سُبْحَتِهِ ‏ ‏جَالِسًا وَيَقْرَأُ السُّورَةَ فَيُرَتِّلُهَا حَتَّى تَكُونَ أَطْوَلَ مِنْ أَطْوَلَ مِنْهَا ‏","","",""],[25237,25237,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ‏ ‏سُبْحَتِهِ ‏ ‏جَالِسًا قَطُّ حَتَّى كَانَ قَبْلَ مَوْتِهِ بِعَامٍ فَكَانَ ‏ ‏يُصَلِّي جَالِسًا فَيَقْرَأُ السُّورَةَ فَيُرَتِّلُهَا حَتَّى تَكُونَ أَطْوَلَ مِنْ أَطْوَلَ مِنْهَا ‏","","",""],[25238,25238,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَأَخْبَرَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏أَنَّ ‏ ‏الْمُطَّلِبَ بْنَ أَبِي وَدَاعَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏حَفْصَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي جَالِسًا حَتَّى كَانَ قَبْلَ وَفَاتِهِ بِعَامٍ ‏ ‏أَوْ عَامَيْنِ ‏","","",""],[25239,25239,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أُمَيَّةَ بْنِ صَفْوَانَ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَؤُمَّنَّ ‏ ‏هَذَا ‏ ‏الْبَيْتَ ‏ ‏جَيْشٌ يَغْزُونَهُ حَتَّى إِذَا كَانُوا ‏ ‏بِالْبَيْدَاءِ ‏ ‏خُسِفَ بِأَوْسَطِهِمْ فَيُنَادِي أَوَّلُهُمْ وَآخِرُهُمْ فَلَا يَنْجُو إِلَّا الشَّرِيدُ الَّذِي يُخْبِرُ عَنْهُمْ فَقَالَ رَجُلٌ كَذَا وَاللَّهِ مَا كَذَبْتُ عَلَى ‏ ‏حَفْصَةَ ‏ ‏وَلَا كَذَبَتْ ‏ ‏حَفْصَةُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25240,25240,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ شَكَلٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنَالُ مِنْ وَجْهِ بَعْضِ نِسَائِهِ وَهُوَ صَائِمٌ ‏","","",""],[25241,25241,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ شَكَلٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏","","",""],[25242,25242,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ شَكَلٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏","","",""],[25243,25243,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ شَكَلٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏","","",""],[25244,25244,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا امْرَأَةٌ يُقَالُ لَهَا ‏ ‏شَفَّاءُ ‏ ‏تَرْقِي مِنْ النَّمْلَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِّمِيهَا ‏ ‏حَفْصَةَ ‏","","",""],[25245,25245,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ سُلَيْمَانَ بْنِ أَبِي حَثْمَةَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُقَالُ لَهَا ‏ ‏الشَّفَّاءُ ‏ ‏كَانَتْ ‏ ‏تَرْقِي مِنْ ‏ ‏النَّمْلَةِ ‏ ‏فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِّمِيهَا ‏ ‏حَفْصَةَ ‏","","",""],[25246,25246,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ وَهُوَ الْجُمَحِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ بَعْضَ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا أَعْلَمُهَا إِلَّا ‏ ‏حَفْصَةَ ‏ ‏سُئِلَتْ عَنْ قِرَاءَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنَّكُمْ لَا تُطِيقُونَهَا قَالَتْ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَنِ الرَّحِيمِ ‏} ‏تَعْنِي التَّرْتِيلَ ‏","","",""],[25247,25247,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏صَفِيَّةَ ابْنَةَ أَبِي عُبَيْدٍ ‏ ‏أَخْبَرَتْهُ أَنَّهَا سَمِعَتْ ‏ ‏حَفْصَةَ ابْنَةَ عُمَرَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏أَوْ بِاللَّهِ وَرَسُولِهِ ‏ ‏أَنْ ‏ ‏تُحِدَّ ‏ ‏عَلَى مَيِّتٍ فَوْقَ ثَلَاثٍ إِلَّا عَلَى زَوْجٍ ‏","","",""],[25248,25248,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏صَفِيَّةَ ابْنَةَ أَبِي عُبَيْدٍ ‏ ‏أَخْبَرَتْهُ أَنَّهَا سَمِعَتْ ‏ ‏حَفْصَةَ ابْنَةَ عُمَرَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏أَوْ تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ ‏ ‏أَنْ ‏ ‏تُحِدَّ ‏ ‏عَلَى مَيِّتٍ فَوْقَ ثَلَاثٍ إِلَّا عَلَى زَوْجٍ فَإِنَّهَا ‏ ‏تُحِدُّ ‏ ‏عَلَيْهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ‏","","",""],[25249,25249,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ ‏ ‏حَفْصَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ ‏ ‏تُحِدَّ ‏ ‏عَلَى مَيِّتٍ فَوْقَ ثَلَاثٍ إِلَّا عَلَى زَوْجٍ ‏","","",""],[25250,25250,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏صَفِيَّةَ ابْنَةَ أَبِي عُبَيْدٍ ‏ ‏حَدَّثَتْهُ عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَوْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ عَنْ كِلْتَيْهِمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ ‏ ‏بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏أَوْ تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ ‏ ‏أَنْ ‏ ‏تُحِدَّ ‏ ‏عَلَى مَيِّتٍ فَوْقَ ثَلَاثَةِ أَيَّامٍ إِلَّا عَلَى زَوْجِهَا ‏","","",""],[25251,25251,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏صَفِيَّةَ ابْنَةَ أَبِي عُبَيْدٍ ‏ ‏حَدَّثَتْهُ عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَوْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ عَنْهُمَا كِلْتَيْهِمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ ‏ ‏تُحِدَّ ‏ ‏فَوْقَ ثَلَاثٍ إِلَّا عَلَى زَوْجِهَا ‏","","",""],[25252,25252,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ لَمْ يُجْمِعْ الصِّيَامَ مَعَ الْفَجْرِ فَلَا صِيَامَ لَهُ ‏","","",""],[25253,25253,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏وَهُوَ ‏ ‏خَتَنُ ‏ ‏سَلَمَةَ الْأَبْرَشِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ عُمَرَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَأْتِي جَيْشٌ مِنْ قِبَلِ الْمَشْرِقِ يُرِيدُونَ رَجُلًا مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏حَتَّى إِذَا كَانُوا ‏ ‏بِالْبَيْدَاءِ ‏ ‏خُسِفَ بِهِمْ فَرَجَعَ مَنْ كَانَ أَمَامَهُمْ لِيَنْظُرَ مَا فَعَلَ الْقَوْمُ فَيُصِيبَهُمْ مِثْلُ مَا أَصَابَهُمْ فَقُلْتُ يَا رَسُولَ اللَّهِ فَكَيْفَ بِمَنْ كَانَ مِنْهُمْ مُسْتَكْرَهًا قَالَ يُصِيبُهُمْ كُلَّهُمْ ذَلِكَ ثُمَّ يَبْعَثُ اللَّهُ كُلَّ امْرِئٍ عَلَى ‏ ‏نِيَّتِهِ ‏","","",""],[25254,25254,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الْأَشْجَعِيُّ الْكُوفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ قَيْسٍ الْمُلَائِيُّ ‏ ‏عَنِ ‏ ‏الْحُرِّ بْنِ الصَّيَّاحِ ‏ ‏عَنْ ‏ ‏هُنَيْدَةَ بْنِ خَالِدٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏قَالَتْ ‏ ‏أَرْبَعٌ لَمْ يَكُنْ يَدَعُهُنَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صِيَامَ ‏ ‏عَاشُورَاءَ ‏ ‏وَالْعَشْرَ وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَالرَّكْعَتَيْنِ قَبْلَ ‏ ‏الْغَدَاةِ ‏","","",""],[25255,25255,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏سَوَاءٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏حَفْصَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ وَيَوْمَ ‏ ‏الِاثْنَيْنِ مِنْ الْجُمُعَةِ الْأُخْرَى ‏","","",""],[25256,25256,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏حَفْصَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَخَذَ ‏ ‏مَضْجَعَهُ ‏ ‏وَضَعَ يَدَهُ الْيُمْنَى تَحْتَ خَدِّهِ الْأَيْمَنِ وَكَانَتْ يَمِينُهُ لِطَعَامِهِ وَطُهُورِهِ وَصَلَاتِهِ وَثِيَابِهِ وَكَانَتْ شِمَالُهُ لِمَا سِوَى ذَلِكَ وَكَانَ يَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ ‏","","",""],[25257,25257,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏سَوَاءٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ عُمَرَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏أَوَى ‏ ‏إِلَى فِرَاشِهِ وَضَعَ يَدَهُ الْيُمْنَى تَحْتَ خَدِّهِ وَقَالَ رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ ثَلَاثًا ‏","","",""],[25258,25258,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏سَوَاءٍ الْخُزَاعِيِّ ‏ ‏عَنِ ‏ ‏حَفْصَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ ‏ ‏وَالِاثْنَيْنِ مِنْ الْجُمُعَةِ الْأُخْرَى ‏","","",""],[25259,25259,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏سَوَاءٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏حَفْصَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَوَى إِلَى فِرَاشِهِ ‏ ‏اضْطَجَعَ ‏ ‏عَلَى يَدِهِ الْيُمْنَى ثُمَّ قَالَ رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ ثَلَاثَ مِرَارٍ وَكَانَ يَجْعَلُ يَمِينَهُ لِأَكْلِهِ وَشُرْبِهِ وَوُضُوئِهِ وَثِيَابِهِ وَأَخْذِهِ وَعَطَائِهِ وَيَجْعَلُ شِمَالَهُ لِمَا سِوَى ذَلِكَ وَكَانَ يَصُومُ ثَلَاثَةَ أَيَّامٍ ‏ ‏مِنْ كُلِّ شَهْرٍ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ ‏ ‏وَالِاثْنَيْنِ مِنْ الْجُمُعَةِ الْأُخْرَى ‏","","",""],[25260,25260,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ يَزِيدَ الْعَطَّارَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏سَوَاءٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَرَادَ أَنْ يَرْقُدَ وَضَعَ يَدَهُ الْيُمْنَى تَحْتَ خَدِّهِ الْأَيْمَنِ ثُمَّ قَالَ اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ ثَلَاثَ مِرَارٍ وَكَانَتْ يَدُهُ الْيُمْنَى لِطَعَامِهِ وَشَرَابِهِ وَكَانَتْ يَدُهُ الْيُسْرَى لِسَائِرِ حَاجَتِهِ ‏","","",""],[25261,25261,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَعِيدٍ الْمُزَنِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏حَفْصَةُ ابْنَةُ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ قَدْ وَضَعَ ‏ ‏ثَوْبَهُ ‏ ‏بَيْنَ فَخِذَيْهِ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَاسْتَأْذَنَ فَأَذِنَ لَهُ وَهُوَ عَلَى هَيْئَتِهِ ثُمَّ ‏ ‏عُمَرُ ‏ ‏بِمِثْلِ هَذِهِ الْقِصَّةِ ثُمَّ ‏ ‏عَلِيٌّ ‏ ‏ثُمَّ نَاسٌ مِنْ أَصْحَابِهِ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَيْئَتِهِ ثُمَّ جَاءَ ‏ ‏عُثْمَانُ ‏ ‏فَاسْتَأْذَنَ فَأَذِنَ لَهُ فَأَخَذَ ثَوْبَهُ ‏ ‏فَتَجَلَّلَهُ ‏ ‏فَتَحَدَّثُوا ثُمَّ خَرَجُوا قُلْتُ يَا رَسُولَ اللَّهِ جَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعَلِيٌّ ‏ ‏وَسَائِرُ أَصْحَابِكَ وَأَنْتَ عَلَى هَيْئَتِكَ فَلَمَّا جَاءَ ‏ ‏عُثْمَانُ ‏ ‏تَجَلَّلْتَ ‏ ‏بِثَوْبِكَ فَقَالَ ‏ ‏أَلَا ‏ ‏أَسْتَحْيِي مِمَّنْ ‏ ‏تَسْتَحْيِي مِنْهُ الْمَلَائِكَةُ ‏","","",""],[25262,25262,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي الْيَعْفُورِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَعِيدٍ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ عُمَرَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَوَضَعَ ثَوْبَهُ بَيْنَ فَخِذَيْهِ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَسْتَأْذِنُ فَأَذِنَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَيْئَتِهِ ثُمَّ جَاءَ ‏ ‏عُمَرُ ‏ ‏يَسْتَأْذِنُ فَأَذِنَ لَهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَيْئَتِهِ وَجَاءَ نَاسٌ مِنْ أَصْحَابِهِ فَأَذِنَ لَهُمْ وَجَاءَ ‏ ‏عَلِيٌّ ‏ ‏يَسْتَأْذِنُ فَأَذِنَ لَهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَيْئَتِهِ ثُمَّ جَاءَ ‏ ‏عُثْمَانُ ‏ ‏فَاسْتَأْذَنَ ‏ ‏فَتَجَلَّلَ ‏ ‏ثَوْبَهُ ثُمَّ أَذِنَ لَهُ فَتَحَدَّثُوا سَاعَةً ثُمَّ خَرَجُوا فَقُلْتُ يَا رَسُولَ اللَّهِ دَخَلَ عَلَيْكَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعَلِيٌّ ‏ ‏وَنَاسٌ مِنْ أَصْحَابِكَ وَأَنْتَ عَلَى هَيْئَتِكَ لَمْ تَتَحَرَّكْ فَلَمَّا دَخَلَ ‏ ‏عُثْمَانُ ‏ ‏تَجَلَّلْتَ ‏ ‏ثَوْبَكَ فَقَالَ ‏ ‏أَلَا ‏ ‏أَسْتَحْيِي مِمَّنْ ‏ ‏تَسْتَحْيِي مِنْهُ الْمَلَائِكَةُ ‏","","",""],[25263,25263,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحُرُّ بْنُ الصَّيَّاحِ ‏ ‏عَنْ ‏ ‏هُنَيْدَةَ بْنِ خَالِدٍ ‏ ‏عَنِ ‏ ‏امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ تِسْعَ ذِي الْحِجَّةِ ‏ ‏وَيَوْمَ عَاشُورَاءَ ‏ ‏وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ أَوَّلَ اثْنَيْنِ مِنْ الشَّهْرِ وَخَمِيسَيْنِ ‏","","",""],[25264,25264,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏أَنَّ ‏ ‏عُطَارِدَ بْنَ حَاجِبٍ ‏ ‏قَدِمَ مَعَهُ ثَوْبُ ‏ ‏دِيبَاجٍ ‏ ‏كَسَاهُ إِيَّاهُ ‏ ‏كِسْرَى ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ اشْتَرَيْتَهُ فَقَالَ ‏ ‏إِنَّمَا يَلْبَسُهُ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏","","",""],[25265,25265,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُمَرَ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏أُرَاهَا ‏ ‏حَفْصَةَ ‏ ‏أَنَّهَا سُئِلَتْ عَنْ قِرَاءَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنَّكُمْ لَا تَسْتَطِيعُونَهَا قَالَ فَقِيلَ لَهَا أَخْبِرِينَا بِهَا قَالَ ‏ ‏فَقَرَأَتْ قِرَاءَةً تَرَسَّلَتْ فِيهَا ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏فَحَكَى لَنَا ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏ثُمَّ قَطَّعَ ‏ { ‏الرَّحْمَنِ الرَّحِيمِ ‏} ‏ثُمَّ قَطَّعَ ‏ { ‏مَالِكِ يَوْمِ الدِّينِ ‏}","","",""],[25266,25266,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏سُبَيْعَةَ ابْنَةَ الْحَارِثِ ‏ ‏وَضَعَتْ بَعْدَ وَفَاةِ ‏ ‏زَوْجِهَا ‏ ‏بِعِشْرِينَ لَيْلَةً ‏ ‏أَوْ نَحْوِ ذَلِكَ ‏ ‏وَأَرَادَتْ التَّزْوِيجَ فَقَالَ لَهَا ‏ ‏أَبُو السَّنَابِلِ ‏ ‏لَيْسَ لَكِ ذَلِكَ حَتَّى يَأْتِيَ عَلَيْكِ آخِرُ ‏ ‏الْأَجَلَيْنِ ‏ ‏فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ تَزَوَّجُ إِذَا شَاءَتْ ‏","","",""],[25267,25267,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا مَاتَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏قُلْتُ غَرِيبٌ وَمَاتَ بِأَرْضِ غُرْبَةٍ ‏ ‏فَأَفَضْتُ ‏ ‏بُكَاءً فَجَاءَتْ امْرَأَةٌ تُرِيدُ أَنْ ‏ ‏تُسْعِدَنِي ‏ ‏مِنْ الصَّعِيدِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُرِيدِينَ أَنْ تُدْخِلِي ‏ ‏الشَّيْطَانَ بَيْتًا قَدْ أَخْرَجَهُ اللَّهُ عَزَّ وَجَلَّ مِنْهُ قَالَتْ فَلَمْ أَبْكِ عَلَيْهِ ‏","","",""],[25268,25268,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏نَبْهَانَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏ذَكَرَتْ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ لِإِحْدَاكُنَّ ‏ ‏مُكَاتَبٌ ‏ ‏فَكَانَ عِنْدَهُ مَا يُؤَدِّي فَلْتَحْتَجِبْ مِنْهُ ‏","","",""],[25269,25269,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ ‏ ‏سَمِعَ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَتْ ‏ ‏الْعَشْرُ ‏ ‏فَأَرَادَ رَجُلٌ أَنْ ‏ ‏يُضَحِّيَ ‏ ‏فَلَا ‏ ‏يَمَسَّ ‏ ‏مِنْ شَعْرِهِ وَلَا مِنْ ‏ ‏بَشَرِهِ ‏","","",""],[25270,25270,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏ابْنِ سُوقَةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏ذَكَرَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَيْشَ الَّذِي يُخْسَفُ بِهِمْ فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏لَعَلَّ فِيهِمْ الْمُكْرَهَ فَقَالَ ‏ ‏إِنَّهُمْ يُبْعَثُونَ عَلَى نِيَّاتِهِمْ ‏","","",""],[25271,25271,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمَّارٍ يَعْنِي الدُّهْنِيَّ ‏ ‏سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُخْبِرُ عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوَائِمُ مِنْبَرِي رَوَاتِبُ فِي الْجَنَّةِ ‏","","",""],[25272,25272,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏سَعِيدٍ يَعْنِي الْمَقْبُرِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏وَهُوَ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏كَذَا قَالَ ‏ ‏سُفْيَانُ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي امْرَأَةٌ أَشُدُّ ‏ ‏ضَفْرَ ‏ ‏رَأْسِي قَالَ ‏ ‏يُجْزِئُكِ ‏ ‏أَنْ تَصُبِّي عَلَيْهِ الْمَاءَ ثَلَاثًا ‏","","",""],[25273,25273,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْكُمْ وَأَنْتُمْ أَشَدُّ تَعْجِيلًا لِلْعَصْرِ مِنْهُ ‏","","",""],[25274,25274,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏سُئِلَتْ ‏ ‏عَائِشَةُ ‏ ‏وَأُمُّ سَلَمَةَ ‏ ‏أَيُّ الْعَمَلِ كَانَ أَعْجَبَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏مَا دَامَ عَلَيْهِ وَإِنْ قَلَّ ‏","","",""],[25275,25275,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏هُنَيْدَةَ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَسَأَلْتُهَا عَنْ الصِّيَامِ فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنِي أَنْ أَصُومَ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ أَوَّلُهَا ‏ ‏الِاثْنَيْنِ وَالْجُمُعَةُ وَالْخَمِيسُ ‏","","",""],[25276,25276,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا وَأَبِي عَلَى ‏ ‏عَائِشَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏قَالَتْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ وَهُوَ ‏ ‏جُنُبٌ ‏ ‏ثُمَّ يَصُومُ ‏","","",""],[25277,25277,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏مَا نَسِيتُ قَوْلَهُ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏وَهُوَ ‏ ‏يُعَاطِيهِمُ اللَّبَنَ وَقَدْ اغْبَرَّ شَعْرُ صَدْرِهِ وَهُوَ يَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْخَيْرَ خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏قَالَ فَرَأَى ‏ ‏عَمَّارًا ‏ ‏فَقَالَ وَيْحَهُ ‏ ‏ابْنُ سُمَيَّةَ ‏ ‏تَقْتُلُهُ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏ ‏قَالَ ‏ ‏فَذَكَرْتُهُ ‏ ‏لِمُحَمَّدٍ يَعْنِي ابْنَ سِيرِينَ ‏ ‏فَقَالَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قُلْتُ نَعَمْ أَمَا إِنَّهَا كَانَتْ تُخَالِطُهَا ‏ ‏تَلِجُ ‏ ‏عَلَيْهَا ‏","","",""],[25278,25278,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَفِينَةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ مِنْ آخِرِ وَصِيَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ الصَّلَاةَ وَمَا مَلَكَتْ أَيْمَانُكُمْ حَتَّى جَعَلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَجْلِجُهَا ‏ ‏فِي صَدْرِهِ وَمَا يَفِيصُ بِهَا لِسَانُهُ ‏","","",""],[25279,25279,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏وَعَبْدِ رَبِّهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ جِمَاعٍ غَيْرِ احْتِلَامٍ ثُمَّ يَصُومُ ‏ ‏وَفِي حَدِيثِ ‏ ‏عَبْدِ رَبِّهِ ‏ ‏فِي رَمَضَانَ ‏","","",""],[25280,25280,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا قَدِمَتْ وَهِيَ مَرِيضَةٌ فَذَكَرَتْ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ قَالَتْ فَسَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏يَقْرَأُ ‏ ‏بِالطُّورِ ‏","","",""],[25281,25281,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ عَبْدِ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ ‏ ‏بِسَبْعٍ وَبِخَمْسٍ لَا يَفْصِلُ بَيْنَهُنَّ بِسَلَامٍ وَلَا بِكَلَامٍ ‏","","",""],[25282,25282,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ابْنِ الْقِبْطِيَّةِ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏الْحَارِثُ بْنُ أَبِي رَبِيعَةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ صَفْوَانَ ‏ ‏وَأَنَا مَعَهُمَا عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَسَأَلَاهَا ‏ ‏عَنْ الْجَيْشِ الَّذِي يُخْسَفُ بِهِ وَكَانَ ذَلِكَ فِي أَيَّامِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَعُوذُ عَائِذٌ بِالْحِجْرِ فَيَبْعَثُ اللَّهُ جَيْشًا فَإِذَا كَانُوا ‏ ‏بِبَيْدَاءَ ‏ ‏مِنْ الْأَرْضِ خُسِفَ بِهِمْ فَقُلْتُ يَا رَسُولَ اللَّهِ فَكَيْفَ بِمَنْ أُخْرِجَ كَارِهًا قَالَ يُخْسَفُ بِهِ مَعَهُمْ وَلَكِنَّهُ يُبْعَثُ عَلَى ‏ ‏نِيَّتِهِ ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِأَبِي جَعْفَرٍ ‏ ‏فَقَالَ ‏ ‏هِيَ ‏ ‏بَيْدَاءُ الْمَدِينَةِ ‏","","",""],[25283,25283,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُمَارَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أُمِّ وَلَدٍ لِإِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَجُرُّ ‏ ‏ذَيْلِي ‏ ‏فَأَمُرُّ بِالْمَكَانِ الْقَذِرِ وَالْمَكَانِ الطَّيِّبِ فَدَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَسَأَلْتُهَا عَنْ ذَلِكَ فَقَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُطَهِّرُهُ مَا بَعْدَهُ ‏","","",""],[25284,25284,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيْهَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏قَالَ فَقَالَ يَا ‏ ‏أُمَّهْ قَدْ خِفْتُ أَنْ يُهْلِكَنِي كَثْرَةُ مَالِي أَنَا أَكْثَرُ ‏ ‏قُرَيْشٍ ‏ ‏مَالًا قَالَتْ يَا بُنَيَّ فَأَنْفِقْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أَصْحَابِي مَنْ لَا يَرَانِي بَعْدَ أَنْ أُفَارِقَهُ ‏ ‏فَخَرَجَ فَلَقِيَ ‏ ‏عُمَرَ ‏ ‏فَأَخْبَرَهُ فَجَاءَ ‏ ‏عُمَرُ ‏ ‏فَدَخَلَ عَلَيْهَا فَقَالَ لَهَا بِاللَّهِ مِنْهُمْ أَنَا فَقَالَتْ لَا وَلَنْ ‏ ‏أُبْلِيَ ‏ ‏أَحَدًا بَعْدَكَ ‏","","",""],[25285,25285,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهَا ‏ ‏مُخَنَّثٌ ‏ ‏وَعِنْدَهَا أَخُوهَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ ‏ ‏وَالْمُخَنَّثُ يَقُولُ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أُمَيَّةَ ‏ ‏إِنْ فَتَحَ اللَّهُ عَلَيْكُمْ ‏ ‏الطَّائِفَ ‏ ‏غَدًا فَعَلَيْكَ ‏ ‏بِابْنَةِ غَيْلَانَ ‏ ‏فَإِنَّهَا ‏ ‏تُقْبِلُ ‏ ‏بِأَرْبَعٍ ‏ ‏وَتُدْبِرُ ‏ ‏بِثَمَانٍ ‏ ‏قَالَ فَسَمِعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏لَا يَدْخُلَنَّ هَذَا عَلَيْكِ ‏","","",""],[25286,25286,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ ‏ ‏تَخْتَصِمُونَ ‏ ‏إِلَيَّ وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ ‏ ‏أَلْحَنَ ‏ ‏بِحُجَّتِهِ مِنْ بَعْضٍ وَإِنَّمَا أَنَا بَشَرٌ ‏ ‏أَقْضِي ‏ ‏لَهُ عَلَى نَحْوِ مَا أَسْمَعُ مِنْهُ فَمَنْ قَضَيْتُ لَهُ ‏ ‏مِنْ حَقِّ أَخِيهِ شَيْئًا فَإِنَّمَا هُوَ نَارٌ فَلَا يَأْخُذْهُ ‏","","",""],[25287,25287,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهَا أَنْ ‏ ‏تُوَافِيَ مَعَهُ صَلَاةَ الصُّبْحِ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏بِمَكَّةَ ‏","","",""],[25288,25288,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ هَلْ لَكَ فِي أُخْتِي قَالَ فَأَصْنَعُ بِهَا مَاذَا قَالَتْ تَزَوَّجُهَا فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتُحِبِّينَ ذَلِكَ فَقَالَتْ نَعَمْ لَسْتُ لَكَ ‏ ‏بِمُخْلِيَةٍ ‏ ‏وَأَحَقُّ مَنْ شَرِكَنِي فِي خَيْرٍ أُخْتِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا لَا تَحِلُّ لِي قَالَتْ فَوَاللَّهِ لَقَدْ بَلَغَنِي أَنَّكَ تَخْطُبُ ‏ ‏دُرَّةَ ابْنَةَ أُمِّ سَلَمَةَ بِنْتَ أَبِي سَلَمَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَتْ تَحِلُّ لِي لَمَا تَزَوَّجْتُهَا قَدْ أَرْضَعَتْنِي وَأَبَاهَا ‏ ‏ثُوَيْبَةُ ‏ ‏مَوْلَاةُ ‏ ‏بَنِي هَاشِمٍ ‏ ‏فَلَا تَعْرِضْنَ عَلَيَّ أَخَوَاتِكُنَّ وَلَا بَنَاتِكُنَّ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ هَلْ لَكَ فِي أُخْتِي ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ ‏ ‏قَالَتْ قُلْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تَزَوَّجُ أُخْتِي ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ بِنْتَ أَبِي سَلَمَةَ ‏ ‏أَخْبَرَتْهُ أَنَّ ‏ ‏أُمَّ حَبِيبَةَ ابْنَةَ أَبِي سُفْيَانَ ‏ ‏أَخْبَرَتْهَا أَنَّهَا قَالَتْ يَا رَسُولَ اللَّهِ انْكِحْ أُخْتِي ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَوَافَقَهُ ‏ ‏ابْنُ أَخِي الزُّهْرِيِّ ‏ ‏وَقَالَ ‏ ‏عُقَيْلٌ ‏ ‏إِنَّ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏قَالَتْ ‏","","",""],[25289,25289,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حَضَرْتُمْ الْمَيِّتَ ‏ ‏أَوْ الْمَرِيضَ ‏ ‏فَقُولُوا خَيْرًا فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ قَالَتْ فَلَمَّا مَاتَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏قَدْ مَاتَ فَقَالَ قُولِي ‏ ‏اللَّهُمَّ اغْفِرْ لِي وَلَهُ ‏ ‏وَأَعْقِبْنِي ‏ ‏مِنْهُ ‏ ‏عُقْبَى ‏ ‏حَسَنَةً ‏ ‏قَالَتْ ‏ ‏فَقُلْتُ ‏ ‏فَأَعْقَبَنِي ‏ ‏اللَّهُ عَزَّ وَجَلَّ مَنْ هُوَ خَيْرٌ لِي مِنْهُ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25290,25290,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا كَانَتْ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلَانِ مِنْ إِنَاءٍ وَاحِدٍ مِنْ الْجَنَابَةِ وَكَانَ يُقَبِّلُهَا وَهُوَ صَائِمٌ ‏","","",""],[25291,25291,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ رَافِعٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حَضَرَ الْعَشَاءُ وَحَضَرَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[25292,25292,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ فَرُّوخَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏فَقَالَتْ إِنَّ زَوْجِي يُقَبِّلُنِي وَهُوَ صَائِمٌ وَأَنَا صَائِمَةٌ فَمَا تَرَيْنَ فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُنِي وَهُوَ صَائِمٌ وَأَنَا صَائِمَةٌ ‏","","",""],[25293,25293,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُمَيْدُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهَا ‏ ‏أَنَّ امْرَأَةً تُوُفِّيَ زَوْجُهَا فَاشْتَكَتْ عَيْنَهَا فَذَكَرُوهَا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَكَرُوا الْكُحْلَ قَالُوا نَخَافُ عَلَى عَيْنِهَا قَالَ قَدْ ‏ ‏كَانَتْ إِحْدَاكُنَّ تَمْكُثُ فِي بَيْتِهَا فِي شَرِّ ‏ ‏أَحْلَاسِهَا ‏ ‏أَوْ فِي ‏ ‏أَحْلَاسِهَا ‏ ‏فِي سِتْرِ بَيْتِهَا ‏ ‏حَوْلًا ‏ ‏فَإِذَا مَرَّ بِهَا كَلْبٌ رَمَتْ ‏ ‏بِبَعْرَةٍ ‏ ‏أَفَلَا أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ‏","","",""],[25294,25294,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفًا فَجَاءَهُ ‏ ‏بِلَالٌ ‏ ‏فَخَرَجَ إِلَى الصَّلَاةِ وَلَمْ يَمَسَّ مَاءً ‏","","",""],[25295,25295,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ ‏ ‏هَلْ عَلَى الْمَرْأَةِ مِنْ غُسْلٍ إِذَا احْتَلَمَتْ قَالَ نَعَمْ إِذَا رَأَتْ الْمَاءَ فَضَحِكَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قَالَتْ أَتَحْتَلِمُ الْمَرْأَةُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبِمَ يُشْبِهُ الْوَلَدُ ‏","","",""],[25296,25296,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا تَزَوَّجَهَا أَقَامَ عِنْدَهَا ثَلَاثَةَ أَيَّامٍ وَقَالَ ‏ ‏إِنَّهُ لَيْسَ بِكِ عَلَى أَهْلِكِ هَوَانٌ وَإِنْ شِئْتِ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ وَإِنْ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ ‏ ‏سَبَّعْتُ ‏ ‏لِنِسَائِي ‏","","",""],[25297,25297,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏رَيْطَةُ ‏ ‏عَنْ ‏ ‏كَبْشَةَ ابْنَةِ أَبِي مَرْيَمَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏أَخْبِرِينِي مَا نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْلَهُ قَالَتْ ‏ ‏نَهَانَا أَنْ ‏ ‏نَعْجُمَ ‏ ‏النَّوَى ‏ ‏طَبْخًا وَأَنْ نَخْلِطَ الزَّبِيبَ وَالتَّمْرَ ‏","","",""],[25298,25298,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمَّارٌ الدُّهْنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَوَائِمُ الْمِنْبَرِ رَوَاتِبُ فِي الْجَنَّةِ ‏","","",""],[25299,25299,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عُثْمَانَ بْنِ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ أَبِي نَصْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُسَاوِرٌ الْحِمْيَرِيُّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِعَلِيٍّ ‏ ‏لَا يُبْغِضُكَ مُؤْمِنٌ وَلَا يُحِبُّكَ مُنَافِقٌ ‏","","",""],[25300,25300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ يَعْنِي ابْنَ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تَذْكُرُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي بَيْتِهَا فَأَتَتْهُ ‏ ‏فَاطِمَةُ ‏ ‏بِبُرْمَةٍ ‏ ‏فِيهَا ‏ ‏خَزِيرَةٌ ‏ ‏فَدَخَلَتْ بِهَا عَلَيْهِ فَقَالَ لَهَا ادْعِي زَوْجَكِ وَابْنَيْكِ قَالَتْ فَجَاءَ ‏ ‏عَلِيٌّ ‏ ‏وَالْحُسَيْنُ ‏ ‏وَالْحَسَنُ ‏ ‏فَدَخَلُوا عَلَيْهِ فَجَلَسُوا يَأْكُلُونَ مِنْ تِلْكَ ‏ ‏الْخَزِيرَةِ ‏ ‏وَهُوَ عَلَى مَنَامَةٍ لَهُ عَلَى ‏ ‏دُكَّانٍ ‏ ‏تَحْتَهُ ‏ ‏كِسَاءٌ ‏ ‏لَهُ ‏ ‏خَيْبَرِيٌّ قَالَتْ وَأَنَا أُصَلِّي فِي الْحُجْرَةِ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ هَذِهِ الْآيَةَ ‏ { ‏إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمْ ‏ ‏الرِّجْسَ ‏ ‏أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا ‏} ‏قَالَتْ فَأَخَذَ فَضْلَ ‏ ‏الْكِسَاءِ ‏ ‏فَغَشَّاهُمْ بِهِ ثُمَّ أَخْرَجَ يَدَهُ فَأَلْوَى بِهَا إِلَى السَّمَاءِ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ هَؤُلَاءِ أَهْلُ بَيْتِي وَخَاصَّتِي فَأَذْهِبْ عَنْهُمْ ‏ ‏الرِّجْسَ ‏ ‏وَطَهِّرْهُمْ تَطْهِيرًا اللَّهُمَّ هَؤُلَاءِ أَهْلُ بَيْتِي وَخَاصَّتِي فَأَذْهِبْ عَنْهُمْ ‏ ‏الرِّجْسَ ‏ ‏وَطَهِّرْهُمْ تَطْهِيرًا قَالَتْ فَأَدْخَلْتُ رَأْسِي الْبَيْتَ فَقُلْتُ وَأَنَا مَعَكُمْ يَا رَسُولَ اللَّهِ قَالَ إِنَّكِ إِلَى خَيْرٍ إِنَّكِ إِلَى خَيْرٍ ‏ ‏قَالَ ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏وَحَدَّثَنِي ‏ ‏أَبُو لَيْلَى ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏عَطَاءٍ ‏ ‏سَوَاءً ‏ ‏قَالَ ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏وَحَدَّثَنِي ‏ ‏دَاوُدُ بْنُ أَبِي عَوْفٍ أَبُو الْحَجَّافِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏بِمِثْلِهِ سَوَاءً ‏","","",""],[25301,25301,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏هَلْ لِي مِنْ أَجْرٍ فِي ‏ ‏بَنِي أَبِي سَلَمَةَ ‏ ‏أَنْ أُنْفِقَ عَلَيْهِمْ وَلَسْتُ بِتَارِكَتِهِمْ هَكَذَا وَهَكَذَا وَهَكَذَا إِنَّمَا ‏ ‏هُمْ بَنِيَّ قَالَ نَعَمْ فِيهِمْ أَجْرٌ مَا أَنْفَقْتِ عَلَيْهِمْ ‏","","",""],[25302,25302,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا اسْتَفْتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي امْرَأَةٍ ‏ ‏تُهَرَاقُ ‏ ‏الدَّمَ فَقَالَ ‏ ‏تَنْتَظِرُ قَدْرَ اللَّيَالِي وَالْأَيَّامِ الَّتِي كَانَتْ تَحِيضُهُنَّ وَقَدْرَهُنَّ مِنْ الشَّهْرِ فَتَدَعُ الصَّلَاةَ ثُمَّ لِتَغْتَسِلْ ‏ ‏وَلْتَسْتَثْفِرْ ‏ ‏ثُمَّ تُصَلِّي ‏","","",""],[25303,25303,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ فَكَيْفَ بِالنِّسَاءِ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏تُرْخِينَ شِبْرًا قُلْتُ إِذَنْ يَنْكَشِفَ عَنْهُنَّ قَالَ فَذِرَاعٌ لَا يَزِدْنَ عَلَيْهِ ‏","","",""],[25304,25304,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ الْحَارِثِ بْنِ الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏رُمَيْثَةَ أُمِّ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَلَّمَنِي صَوَاحِبِي أَنْ أُكَلِّمَ رَسُولَ اللَّهِ أَنْ يَأْمُرَ النَّاسَ فَيُهْدُونَ لَهُ حَيْثُ كَانَ فَإِنَّهُمْ ‏ ‏يَتَحَرَّوْنَ ‏ ‏بِهَدِيَّتِهِ يَوْمَ ‏ ‏عَائِشَةَ ‏ ‏وَإِنَّا نُحِبُّ الْخَيْرَ كَمَا تُحِبُّهُ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ صَوَاحِبِي كَلَّمْنَنِي أَنْ أُكَلِّمَكَ لِتَأْمُرَ النَّاسَ أَنْ يُهْدُوا لَكَ حَيْثُ كُنْتَ فَإِنَّ النَّاسَ ‏ ‏يَتَحَرَّوْنَ ‏ ‏بِهَدَايَاهُمْ يَوْمَ ‏ ‏عَائِشَةَ ‏ ‏وَإِنَّمَا نُحِبُّ الْخَيْرَ كَمَا تُحِبُّ ‏ ‏عَائِشَةُ ‏ ‏قَالَتْ فَسَكَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يُرَاجِعْنِي فَجَاءَنِي صَوَاحِبِي فَأَخْبَرْتُهُنَّ أَنَّهُ لَمْ يُكَلِّمْنِي فَقُلْنَ لَا تَدَعِيهِ وَمَا هَذَا حِينَ تَدَعِينَهُ قَالَتْ ثُمَّ ‏ ‏دَارَ ‏ ‏فَكَلَّمْتُهُ فَقُلْتُ إِنَّ صَوَاحِبِي قَدْ أَمَرْنَنِي أَنْ أُكَلِّمَكَ تَأْمُرُ النَّاسَ فَلْيُهْدُوا لَكَ حَيْثُ كُنْتَ فَقَالَتْ لَهُ مِثْلَ تِلْكَ الْمَقَالَةِ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏كُلُّ ذَلِكَ يَسْكُتُ عَنْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ يَا ‏ ‏أُمَّ سَلَمَةَ ‏ ‏لَا تُؤْذِينِي فِي ‏ ‏عَائِشَةَ ‏ ‏فَإِنَّهُ وَاللَّهِ مَا نَزَلَ عَلَيَّ الْوَحْيُ وَأَنَا فِي بَيْتِ امْرَأَةٍ مِنْ نِسَائِي غَيْرَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ أَعُوذُ بِاللَّهِ أَنْ أَسُوءَكَ فِي ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُخْتِهِ ‏ ‏رُمَيْثَةَ ابْنَةِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ نِسَاءَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْنَ لَهَا إِنَّ النَّاسَ ‏ ‏يَتَحَرَّوْنَ ‏ ‏بِهَدَايَاهُمْ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[25305,25305,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ يَعْنِي ابْنَ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏سَاهِمُ ‏ ‏الْوَجْهِ قَالَتْ فَحَسِبْتُ أَنَّ ذَلِكَ مِنْ وَجَعٍ فَقُلْتُ يَا نَبِيَّ اللَّهِ مَا لَكَ سَاهِمُ الْوَجْهِ قَالَ ‏ ‏مِنْ أَجْلِ الدَّنَانِيرِ السَّبْعَةِ الَّتِي أَتَتْنَا أَمْسِ أَمْسَيْنَا وَهِيَ فِي ‏ ‏خُصْمِ ‏ ‏الْفِرَاشِ ‏","","",""],[25306,25306,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الْعَصْرِ فَصَلَّى رَكْعَتَيْنِ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مَا هَذِهِ الصَّلَاةُ مَا كُنْتَ تُصَلِّيهَا قَالَ قَدِمَ وَفْدُ ‏ ‏بَنِي تَمِيمٍ ‏ ‏فَحَبَسُونِي عَنْ رَكْعَتَيْنِ كُنْتُ أَرْكَعُهُمَا بَعْدَ الظُّهْرِ ‏","","",""],[25307,25307,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ أَبُو تَمَّامٍ الْأَسَدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حُمَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ الْمَخْزُومِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا بُنَيَّ أَلَا أُحَدِّثُكَ بِمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ بَلَى يَا ‏ ‏أُمَّهْ قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَنْفَقَ عَلَى ابْنَتَيْنِ أَوْ أُخْتَيْنِ أَوْ ذَوَاتَيْ قَرَابَةٍ يَحْتَسِبُ النَّفَقَةَ عَلَيْهِمَا حَتَّى يُغْنِيَهُمَا اللَّهُ مِنْ فَضْلِهِ عَزَّ وَجَلَّ ‏ ‏أَوْ يَكْفِيَهُمَا ‏ ‏كَانَتَا لَهُ سِتْرًا مِنْ النَّارِ ‏","","",""],[25308,25308,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ شَعْبَانَ وَرَمَضَانَ ‏","","",""],[25309,25309,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَارُونُ النَّحْوِيُّ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَهَا ‏ { ‏إِنَّهُ عَمِلَ ‏ ‏غَيْرَ ‏ ‏صَالِحٍ ‏}","","",""],[25310,25310,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ بَهْرَامَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ ‏","","",""],[25311,25311,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجُّ جِهَادُ كُلِّ ضَعِيفٍ ‏","","",""],[25312,25312,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏مَوْلًى ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي ‏ ‏دُبُرِ ‏ ‏الْفَجْرِ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَعَمَلًا مُتَقَبَّلًا وَرِزْقًا طَيِّبًا ‏","","",""],[25313,25313,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ يَعْنِي ابْنَ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏وَهْبٍ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَلَمْ تَخْتَمِرْ فَقَالَ ‏ ‏لَيَّةً ‏ ‏لَا ‏ ‏لَيَّتَيْنِ ‏","","",""],[25314,25314,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي حُجْرَةِ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَمَرَّ بَيْنَ يَدَيْهِ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَوْ ‏ ‏عُمَرُ ‏ ‏فَقَالَ بِيَدِهِ هَكَذَا قَالَ فَرَجَعَ قَالَ فَمَرَّتْ ‏ ‏ابْنَةُ أُمِّ سَلَمَةَ ‏ ‏فَقَالَ بِيَدِهِ هَكَذَا قَالَ فَمَضَتْ فَلَمَّا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هُنَّ أَغْلَبُ ‏","","",""],[25315,25315,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏شَكَّ هُوَ ‏ ‏يَعْنِي ‏ ‏عَبْدَ اللَّهِ بْنَ سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِإِحْدَاهُمَا ‏ ‏لَقَدْ دَخَلَ عَلَيَّ الْبَيْتَ مَلَكٌ لَمْ يَدْخُلْ عَلَيَّ قَبْلَهَا فَقَالَ لِي إِنَّ ابْنَكَ هَذَا ‏ ‏حُسَيْنٌ ‏ ‏مَقْتُولٌ وَإِنْ شِئْتَ أَرَيْتُكَ مِنْ تُرْبَةِ الْأَرْضِ الَّتِي يُقْتَلُ بِهَا قَالَ فَأَخْرَجَ تُرْبَةً حَمْرَاءَ ‏","","",""],[25316,25316,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏حِضْتُ وَأَنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏ثَوْبٍ ‏ ‏قَالَتْ ‏ ‏فَانْسَلَلْتُ ‏ ‏فَقَالَ ‏ ‏أَنُفِسْتِ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ وَجَدْتُ مَا تَجِدُ النِّسَاءُ قَالَ ‏ ‏ذَاكَ مَا كُتِبَ عَلَى بَنَاتِ ‏ ‏آدَمَ ‏ ‏قَالَتْ فَانْطَلَقْتُ فَأَصْلَحْتُ مِنْ شَأْنِي ‏ ‏فَاسْتَثْفَرْتُ ‏ ‏بِثَوْبٍ ثُمَّ جِئْتُ فَدَخَلْتُ مَعَهُ فِي لِحَافِهِ ‏","","",""],[25317,25317,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ مَمْلَكٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ وَقِرَاءَتِهِ فَقَالَتْ مَا لَكُمْ وَلِصَلَاتِهِ وَلِقِرَاءَتِهِ كَانَ ‏ ‏يُصَلِّي قَدْرَ مَا يَنَامُ وَيَنَامُ قَدْرَ مَا ‏ ‏يُصَلِّي وَإِذَا هِيَ ‏ ‏تَنْعَتُ ‏ ‏قِرَاءَةً مُفَسَّرَةً حَرْفًا حَرْفًا ‏","","",""],[25318,25318,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ أَبِي رَاشِدٍ ‏ ‏عَنْ ‏ ‏مُنْذِرٍ الثَّوْرِيِّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏امْرَأَةٌ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏هِيَ حَيَّةٌ الْيَوْمَ إِنْ شِئْتَ أَدْخَلْتُكَ عَلَيْهَا قُلْتُ لَا حَدِّثْنِي ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَدَخَلَ عَلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّهُ غَضْبَانُ فَاسْتَتَرْتُ مِنْهُ بِكُمِّ ‏ ‏دِرْعِي ‏ ‏فَتَكَلَّمَ بِكَلَامٍ لَمْ أَفْهَمْهُ فَقُلْتُ يَا ‏ ‏أُمَّ الْمُؤْمِنِينَ ‏ ‏كَأَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ وَهُوَ غَضْبَانُ فَقَالَتْ نَعَمْ أَوَمَا سَمِعْتِ مَا قَالَ قُلْتُ وَمَا قَالَ قَالَتْ قَالَ ‏ ‏إِنَّ الشَّرَّ إِذَا فَشَا فِي الْأَرْضِ فَلَمْ يُتَنَاهَ عَنْهُ أَرْسَلَ اللَّهُ عَزَّ وَجَلَّ بَأْسَهُ عَلَى أَهْلِ الْأَرْضِ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ وَفِيهِمْ ‏ ‏الصَّالِحُونَ قَالَتْ قَالَ نَعَمْ وَفِيهِمْ الصَّالِحُونَ يُصِيبُهُمْ مَا أَصَابَ النَّاسَ ثُمَّ يَقْبِضُهُمْ اللَّهُ عَزَّ وَجَلَّ إِلَى مَغْفِرَتِهِ وَرِضْوَانِهِ ‏ ‏أَوْ إِلَى رِضْوَانِهِ وَمَغْفِرَتِهِ ‏","","",""],[25319,25319,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ضَبَّةَ بْنِ مُحْصِنٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ سَتَكُونُ أُمَرَاءُ تَعْرِفُونَ وَتُنْكِرُونَ فَمَنْ أَنْكَرَ فَقَدْ بَرِئَ وَمَنْ كَرِهَ فَقَدْ سَلِمَ وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ قَالُوا يَا رَسُولَ اللَّهِ أَفَلَا نُقَاتِلُهُمْ قَالَ لَا مَا صَلَّوْا لَكُمْ الْخَمْسَ ‏","","",""],[25320,25320,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّهُ لَيْسَ أَحَدٌ مِنْ أَوْلِيَائِي ‏ ‏تَعْنِي شَاهِدًا ‏ ‏فَقَالَ إِنَّهُ لَيْسَ أَحَدٌ مِنْ أَوْلِيَائِكِ شَاهِدٌ وَلَا غَائِبٌ يَكْرَهُ ذَلِكَ فَقَالَتْ يَا ‏ ‏عُمَرُ ‏ ‏زَوِّجْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَزَوَّجَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنِّي لَا أَنْقُصُكِ مِمَّا أَعْطَيْتُ أَخَوَاتِكِ ‏ ‏رَحْيَيْنِ ‏ ‏وَجَرَّةً ‏ ‏وَمِرْفَقَةً ‏ ‏مِنْ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهَا لِيفٌ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِيهَا لِيَدْخُلَ بِهَا فَإِذَا رَأَتْهُ أَخَذَتْ ‏ ‏زَيْنَبَ ‏ ‏ابْنَتَهَا فَجَعَلَتْهَا فِي حِجْرِهَا فَيَنْصَرِفُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلِمَ ذَلِكَ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏وَكَانَ أَخَاهَا مِنْ الرَّضَاعَةِ فَأَتَاهَا وَقَالَ أَيْنَ هَذِهِ ‏ ‏الْمَشْقُوحَةُ ‏ ‏الْمَقْبُوحَةُ الَّتِي قَدْ آذَيْتِ بِهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَهَا فَذَهَبَ بِهَا فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ عَلَيْهَا فَجَعَلَ يَضْرِبُ بِبَصَرِهِ فِي نَوَاحِي الْبَيْتِ فَقَالَ مَا فَعَلَتْ ‏ ‏زَنَابُ ‏ ‏فَقَالَتْ جَاءَ ‏ ‏عَمَّارٌ ‏ ‏فَأَخَذَهَا فَذَهَبَ بِهَا فَدَخَلَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ لَهَا إِنْ شِئْتِ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ ‏ ‏سَبَّعْتُ ‏ ‏وَإِنْ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ ‏ ‏سَبَّعْتُ ‏ ‏لِنِسَائِي ‏","","",""],[25321,25321,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عُبَيْدَةَ بْنُ عَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَنْ ‏ ‏أُمِّهِ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏يُحَدِّثَانِهِ ‏ ‏ذَلِكَ جَمِيعًا عَنْهَا ‏ ‏قَالَتْ ‏ ‏كَانَتْ لَيْلَتِي الَّتِي يَصِيرُ إِلَيَّ فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَاءَ ‏ ‏يَوْمِ النَّحْرِ ‏ ‏قَالَتْ فَصَارَ إِلَيَّ قَالَتْ فَدَخَلَ عَلَيَّ ‏ ‏وَهْبُ بْنُ زَمْعَةَ ‏ ‏وَمَعَهُ رَجُلٌ مِنْ آلِ ‏ ‏أَبِي أُمَيَّةَ ‏ ‏مُتَقَمِّصَيْنِ ‏ ‏قَالَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِوَهْبٍ ‏ ‏هَلْ ‏ ‏أَفَضْتَ ‏ ‏بَعْدُ ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏قَالَ لَا وَاللَّهِ يَا رَسُولَ اللَّهِ قَالَ انْزِعْ عَنْكَ الْقَمِيصَ قَالَ فَنَزَعَهُ مِنْ رَأْسِهِ وَنَزَعَ صَاحِبُهُ قَمِيصَهُ مِنْ رَأْسِهِ ثُمَّ قَالُوا وَلِمَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِنَّ هَذَا يَوْمٌ رُخِّصَ لَكُمْ إِذَا أَنْتُمْ رَمَيْتُمْ الْجَمْرَةَ أَنْ تَحِلُّوا ‏ ‏يَعْنِي مِنْ كُلِّ مَا حُرِمْتُمْ مِنْهُ إِلَّا مِنْ النِّسَاءِ إِذَا أَنْتُمْ أَمْسَيْتُمْ قَبْلَ أَنْ تَطُوفُوا بِهَذَا ‏ ‏الْبَيْتِ ‏ ‏عُدْتُمْ حُرُمًا كَهَيْئَتِكُمْ قَبْلَ أَنْ تَرْمُوا الْجَمْرَةَ حَتَّى تَطُوفُوا بِهِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏وَحَدَّثَتْنِي ‏ ‏أُمُّ قَيْسٍ ابْنَةُ مِحْصَنٍ ‏ ‏وَكَانَتْ جَارَةً لَهُمْ ‏ ‏قَالَتْ ‏ ‏خَرَجَ مِنْ عِنْدِي ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ ‏ ‏فِي نَفَرٍ مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏مُتَقَمِّصِينَ ‏ ‏عَشِيَّةَ ‏ ‏يَوْمِ النَّحْرِ ‏ ‏ثُمَّ رَجَعُوا إِلَيَّ عِشَاءً قُمُصُهُمْ عَلَى أَيْدِيهِمْ يَحْمِلُونَهَا قَالَتْ فَقُلْتُ أَيْ ‏ ‏عُكَّاشَةُ ‏ ‏مَا لَكُمْ خَرَجْتُمْ مُتَقَمِّصِينَ ثُمَّ رَجَعْتُمْ وَقُمُصُكُمْ عَلَى أَيْدِيكُمْ تَحْمِلُونَهَا فَقَالَ أَخْبَرَتْنَا ‏ ‏أُمُّ قَيْسٍ ‏ ‏كَانَ هَذَا يَوْمًا قَدْ رُخِّصَ لَنَا فِيهِ إِذَا نَحْنُ رَمَيْنَا الْجَمْرَةَ حَلَلْنَا مِنْ كُلِّ مَا حُرِمْنَا مِنْهُ إِلَّا مَا كَانَ مِنْ النِّسَاءِ حَتَّى نَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏فَإِذَا أَمْسَيْنَا وَلَمْ نَطُفْ بِهِ صِرْنَا حُرُمًا كَهَيْئَتِنَا قَبْلَ أَنْ نَرْمِيَ الْجَمْرَةَ حَتَّى نَطُوفَ بِهِ وَلَمْ نَطُفْ فَجَعَلْنَا قُمُصَنَا كَمَا تَرَيْنَ ‏","","",""],[25322,25322,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذُيُولُ ‏ ‏النِّسَاءِ شِبْرٌ قُلْتُ إِذَنْ تَبْدُوَ أَقْدَامُهُنَّ يَا رَسُولَ اللَّهِ قَالَ فَذِرَاعٌ لَا تَزِدْنَ عَلَيْهِ ‏","","",""],[25323,25323,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى يَعْنِي ابْنَ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَسْأَلُهَا هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ فَإِنْ قَالَتْ لَا فَقُلْ لَهَا إِنَّ ‏ ‏عَائِشَةَ ‏ ‏تُخْبِرُ النَّاسَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُقَبِّلُ وَهُوَ صَائِمٌ قَالَ فَسَأَلَهَا أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ قَالَتْ لَا قُلْتُ إِنَّ ‏ ‏عَائِشَةَ ‏ ‏تُخْبِرُ النَّاسَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ قَالَتْ لَعَلَّهُ إِيَّاهَا كَانَ لَا يَتَمَالَكُ عَنْهَا حُبًّا أَمَّا إِيَّايَ فَلَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبُو قَيْسٍ ‏ ‏مَوْلَى ‏ ‏عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏بَعَثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[25324,25324,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَأَخْرَجَتْ إِلَيْنَا مِنْ شَعْرِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ ‏ ‏مَخْضُوبٌ ‏ ‏أَحْمَرُ بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏","","",""],[25325,25325,"","","‏ ‏حَدَّثَنَا ‏ ‏سَيَّارٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرٌ يَعْنِي ابْنَ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ حَبِيبٍ ‏ ‏خَتَنُ ‏ ‏مَالِكِ بْنِ دِينَارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَيْخٌ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصْلِحِي لَنَا الْمَجْلِسَ فَإِنَّهُ يَنْزِلُ مَلَكٌ إِلَى الْأَرْضِ لَمْ يَنْزِلْ إِلَيْهَا قَطُّ ‏","","",""],[25326,25326,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ يَزِيدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏نَبْهَانَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏حَدَّثَتْهُ قَالَتْ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَيْمُونَةُ ‏ ‏فَأَقْبَلَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏حَتَّى دَخَلَ عَلَيْهِ وَذَلِكَ بَعْدَ أَنْ أَمَرَنَا بِالْحِجَابِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجِبَا مِنْهُ فَقُلْنَا يَا رَسُولَ اللَّهِ أَلَيْسَ أَعْمَى لَا يُبْصِرُنَا وَلَا يَعْرِفُنَا قَالَ أَفَعَمْيَاوَانِ أَنْتُمَا لَسْتُمَا تُبْصِرَانِهِ ‏","","",""],[25327,25327,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏وَهْبٍ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَهِيَ تَخْتَمِرُ فَقَالَ ‏ ‏لَيَّةً ‏ ‏لَا ‏ ‏لَيَّتَيْنِ ‏","","",""],[25328,25328,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ أَبِي مُطِيعٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَأَخْرَجَتْ إِلَيْنَا شَعْرًا مِنْ شَعْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَخْضُوبًا ‏ ‏بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏","","",""],[25329,25329,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمُعَدِّلِ عَطِيَّةَ الطُّفَاوِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏حَدَّثَتْهُ قَالَتْ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي يَوْمًا إِذْ قَالَتْ الْخَادِمُ إِنَّ ‏ ‏عَلِيًّا ‏ ‏وَفَاطِمَةَ ‏ ‏بِالسُّدَّةِ ‏ ‏قَالَتْ فَقَالَ لِي قُومِي فَتَنَحَّيْ لِي عَنْ أَهْلِ بَيْتِي قَالَتْ فَقُمْتُ فَتَنَحَّيْتُ فِي الْبَيْتِ قَرِيبًا فَدَخَلَ ‏ ‏عَلِيٌّ ‏ ‏وَفَاطِمَةُ ‏ ‏وَمَعَهُمَا ‏ ‏الْحَسَنُ ‏ ‏وَالْحُسَيْنُ ‏ ‏وَهُمَا صَبِيَّانِ صَغِيرَانِ فَأَخَذَ الصَّبِيَّيْنِ فَوَضَعَهُمَا فِي حِجْرِهِ فَقَبَّلَهُمَا قَالَ وَاعْتَنَقَ ‏ ‏عَلِيًّا ‏ ‏بِإِحْدَى يَدَيْهِ ‏ ‏وَفَاطِمَةَ ‏ ‏بِالْيَدِ الْأُخْرَى فَقَبَّلَ ‏ ‏فَاطِمَةَ ‏ ‏وَقَبَّلَ ‏ ‏عَلِيًّا ‏ ‏فَأَغْدَفَ ‏ ‏عَلَيْهِمْ ‏ ‏خَمِيصَةً ‏ ‏سَوْدَاءَ فَقَالَ ‏ ‏اللَّهُمَّ إِلَيْكَ لَا إِلَى النَّارِ أَنَا وَأَهْلُ بَيْتِي قَالَتْ فَقُلْتُ وَأَنَا يَا رَسُولَ اللَّهِ فَقَالَ وَأَنْتِ ‏","","",""],[25330,25330,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏هِنْدِ بِنْتِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ قَامَ النِّسَاءُ حِينَ يَقْضِي تَسْلِيمَهُ وَيَمْكُثُ فِي مَكَانِهِ يَسِيرًا قَبْلَ أَنْ يَقُومَ ‏","","",""],[25331,25331,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏أَبِي السَّمْحِ ‏ ‏عَنِ ‏ ‏السَّائِبِ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَيْرُ مَسَاجِدِ النِّسَاءِ ‏ ‏قَعْرُ ‏ ‏بُيُوتِهِنَّ ‏","","",""],[25332,25332,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الْفَزَارِيَّ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ ذُؤَيْبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏أَبِي سَلَمَةَ ‏ ‏وَقَدْ ‏ ‏شَقَّ ‏ ‏بَصَرُهُ فَأَغْمَضَهُ ثُمَّ قَالَ إِنَّ الرُّوحَ إِذَا قُبِضَ تَبِعَهُ الْبَصَرُ ‏ ‏فَضَجَّ ‏ ‏نَاسٌ مِنْ أَهْلِهِ فَقَالَ لَا تَدْعُوا عَلَى أَنْفُسِكُمْ إِلَّا بِخَيْرٍ فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِأَبِي سَلَمَةَ ‏ ‏وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ وَاخْلُفْهُ فِي ‏ ‏عَقِبِهِ ‏ ‏فِي ‏ ‏الْغَابِرِينَ ‏ ‏وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِينَ اللَّهُمَّ افْسَحْ فِي قَبْرِهِ وَنَوِّرْ لَهُ فِيهِ ‏","","",""],[25333,25333,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏مَا قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى كَانَ أَكْثَرَ صَلَاتِهِ جَالِسًا ‏","","",""],[25334,25334,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏هِنْدِ بِنْتِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَكَانَ ‏ ‏لِهِنْدٍ ‏ ‏أَزْرَارٌ فِي كُمِّهَا ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏اسْتَيْقَظَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ وَهُوَ يَقُولُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ مَا فُتِحَ اللَّيْلَةَ مِنْ الْخَزَائِنِ لَا إِلَهَ إِلَّا اللَّهُ مَا أُنْزِلَ اللَّيْلَةَ مِنْ الْفِتْنَةِ مَنْ يُوقِظُ صَوَاحِبَ الْحُجَرِ يَا رُبَّ كَاسِيَاتٍ فِي الدُّنْيَا عَارِيَاتٍ فِي الْآخِرَةِ ‏","","",""],[25335,25335,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَفْلَحُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَافِعٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏تُحَدِّثُ أَنَّهَا ‏ ‏سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى الْمِنْبَرِ وَهِيَ تَمْتَشِطُ أَيُّهَا النَّاسُ فَقَالَتْ ‏ ‏لِمَاشِطَتِهَا ‏ ‏لُفِّي رَأْسِي قَالَتْ فَقَالَتْ فَدَيْتُكِ إِنَّمَا يَقُولُ أَيُّهَا النَّاسُ قُلْتُ ‏ ‏وَيْحَكِ ‏ ‏أَوَلَسْنَا مِنْ النَّاسِ فَلَفَّتْ رَأْسَهَا وَقَامَتْ فِي حُجْرَتِهَا فَسَمِعَتْهُ يَقُولُ أَيُّهَا النَّاسُ ‏ ‏بَيْنَمَا أَنَا عَلَى الْحَوْضِ جِيءَ بِكُمْ ‏ ‏زُمَرًا ‏ ‏فَتَفَرَّقَتْ بِكُمْ الطُّرُقُ فَنَادَيْتُكُمْ أَلَا هَلُمُّوا إِلَى الطَّرِيقِ فَنَادَانِي مُنَادٍ مِنْ بَعْدِي فَقَالَ إِنَّهُمْ قَدْ بَدَّلُوا بَعْدَكَ فَقُلْتُ أَلَا ‏ ‏سُحْقًا ‏ ‏أَلَا ‏ ‏سُحْقًا ‏","","",""],[25336,25336,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ مَمْلَكٍ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ قَالَتْ كَانَ ‏ ‏يُصَلِّي الْعِشَاءَ الْآخِرَةَ ثُمَّ يُسَبِّحُ ثُمَّ ‏ ‏يُصَلِّي بَعْدَهَا مَا شَاءَ اللَّهُ مِنْ اللَّيْلِ ثُمَّ يَنْصَرِفُ فَيَرْقُدُ مِثْلَ مَا صَلَّى ثُمَّ يَسْتَيْقِظُ مِنْ نَوْمَتِهِ تِلْكَ فَيُصَلِّي مِثْلَ مَا نَامَ وَصَلَاتُهُ الْآخِرَةُ تَكُونُ إِلَى الصُّبْحِ ‏","","",""],[25337,25337,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ الْمِصْرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ أَسْلَمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏حَجَجْتُ مَعَ ‏ ‏مَوَالِيَّ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أَعْتَمِرُ قَبْلَ أَنْ أَحُجَّ قَالَتْ إِنْ شِئْتَ اعْتَمِرْ قَبْلَ أَنْ تَحُجَّ وَإِنْ شِئْتَ بَعْدَ أَنْ تَحُجَّ قَالَ فَقُلْتُ إِنَّهُمْ يَقُولُونَ مَنْ كَانَ ‏ ‏صَرُورَةً ‏ ‏فَلَا يَصْلُحُ أَنْ يَعْتَمِرَ قَبْلَ أَنْ يَحُجَّ قَالَ فَسَأَلْتُ ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ فَقُلْنَ مِثْلَ مَا قَالَتْ فَرَجَعْتُ إِلَيْهَا فَأَخْبَرْتُهَا بِقَوْلِهِنَّ قَالَ فَقَالَتْ نَعَمْ ‏ ‏وَأَشْفِيكَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَهِلُّوا ‏ ‏يَا آلَ ‏ ‏مُحَمَّدٍ ‏ ‏بِعُمْرَةٍ فِي حَجٍّ ‏","","",""],[25338,25338,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَصْحَابِي مَنْ لَا أَرَاهُ وَلَا يَرَانِي بَعْدَ أَنْ أَمُوتَ أَبَدًا ‏ ‏قَالَ ‏ ‏فَبَلَغَ ذَلِكَ ‏ ‏عُمَرَ ‏ ‏قَالَ فَأَتَاهَا ‏ ‏يَشْتَدُّ ‏ ‏أَوْ يُسْرِعُ شَكَّ ‏ ‏شَاذَانُ ‏ ‏قَالَ فَقَالَ لَهَا ‏ ‏أَنْشُدُكِ ‏ ‏بِاللَّهِ أَنَا مِنْهُمْ قَالَتْ لَا وَلَنْ أُبَرِّئَ أَحَدًا بَعْدَكَ أَبَدًا ‏","","",""],[25339,25339,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ يَعْنِي ابْنَ بَهْرَامَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ جَاءَ ‏ ‏نَعْيُ ‏ ‏الْحُسَيْنِ بْنِ عَلِيٍّ ‏ ‏لَعَنَتْ أَهْلَ ‏ ‏الْعِرَاقِ ‏ ‏فَقَالَتْ قَتَلُوهُ قَتَلَهُمْ اللَّهُ ‏ ‏غَرُّوهُ ‏ ‏وَذَلُّوهُ قَتَلَهُمْ اللَّهُ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَتْهُ ‏ ‏فَاطِمَةُ ‏ ‏غَدِيَّةً ‏ ‏بِبُرْمَةٍ ‏ ‏قَدْ صَنَعَتْ لَهُ فِيهَا ‏ ‏عَصِيدَةً ‏ ‏تَحْمِلُهُ فِي طَبَقٍ لَهَا حَتَّى وَضَعَتْهَا بَيْنَ يَدَيْهِ فَقَالَ لَهَا أَيْنَ ابْنُ عَمِّكِ قَالَتْ هُوَ فِي الْبَيْتِ قَالَ فَاذْهَبِي فَادْعِيهِ ‏ ‏وَائْتِنِي بِابْنَيْهِ قَالَتْ فَجَاءَتْ تَقُودُ ابْنَيْهَا كُلُّ وَاحِدٍ مِنْهُمَا بِيَدٍ ‏ ‏وَعَلِيٌّ ‏ ‏يَمْشِي فِي إِثْرِهِمَا حَتَّى دَخَلُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَجْلَسَهُمَا فِي حِجْرِهِ وَجَلَسَ ‏ ‏عَلِيٌّ ‏ ‏عَنْ يَمِينِهِ وَجَلَسَتْ ‏ ‏فَاطِمَةُ ‏ ‏عَنْ يَسَارِهِ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَاجْتَبَذَ ‏ ‏مِنْ تَحْتِي ‏ ‏كِسَاءً ‏ ‏خَيْبَرِيًّا كَانَ بِسَاطًا لَنَا عَلَى ‏ ‏الْمَنَامَةِ ‏ ‏فِي ‏ ‏الْمَدِينَةِ ‏ ‏فَلَفَّهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِمْ جَمِيعًا فَأَخَذَ بِشِمَالِهِ طَرَفَيْ ‏ ‏الْكِسَاءِ ‏ ‏وَأَلْوَى بِيَدِهِ الْيُمْنَى إِلَى رَبِّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏اللَّهُمَّ أَهْلِي أَذْهِبْ عَنْهُمْ ‏ ‏الرِّجْسَ ‏ ‏وَطَهِّرْهُمْ تَطْهِيرًا اللَّهُمَّ أَهْلُ بَيْتِي أَذْهِبْ عَنْهُمْ ‏ ‏الرِّجْسَ ‏ ‏وَطَهِّرْهُمْ تَطْهِيرًا اللَّهُمَّ أَهْلُ بَيْتِي أَذْهِبْ عَنْهُمْ ‏ ‏الرِّجْسَ ‏ ‏وَطَهِّرْهُمْ تَطْهِيرًا قُلْتُ يَا رَسُولَ اللَّهِ أَلَسْتُ مِنْ أَهْلِكَ قَالَ بَلَى فَادْخُلِي فِي ‏ ‏الْكِسَاءِ ‏ ‏قَالَتْ فَدَخَلْتُ فِي ‏ ‏الْكِسَاءِ ‏ ‏بَعْدَمَا قَضَى دُعَاءَهُ لِابْنِ عَمِّهِ ‏ ‏عَلِيٍّ ‏ ‏وَابْنَيْهِ وَابْنَتِهِ ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏","","",""],[25340,25340,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تُحَدِّثُ ‏ ‏زَعَمَتْ أَنَّ ‏ ‏فَاطِمَةَ ‏ ‏جَاءَتْ إِلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَشْتَكِي إِلَيْهِ الْخِدْمَةَ فَقَالَتْ يَا رَسُولَ اللَّهِ وَاللَّهِ لَقَدْ ‏ ‏مَجِلَتْ ‏ ‏يَدَيَّ مِنْ ‏ ‏الرَّحَى ‏ ‏أَطْحَنُ مَرَّةً وَأَعْجِنُ مَرَّةً فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ يَرْزُقْكِ اللَّهُ شَيْئًا يَأْتِكِ وَسَأَدُلُّكِ عَلَى خَيْرٍ مِنْ ذَلِكَ ‏ ‏إِذَا لَزِمْتِ ‏ ‏مَضْجَعَكِ ‏ ‏فَسَبِّحِي اللَّهَ ثَلَاثًا وَثَلَاثِينَ وَكَبِّرِي ثَلَاثًا وَثَلَاثِينَ وَاحْمَدِي أَرْبَعًا وَثَلَاثِينَ فَذَلِكَ مِائَةٌ فَهُوَ خَيْرٌ لَكِ مِنْ الْخَادِمِ وَإِذَا صَلَّيْتِ صَلَاةَ الصُّبْحِ فَقُولِي لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ بِيَدِهِ الْخَيْرُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مَرَّاتٍ بَعْدَ صَلَاةِ الصُّبْحِ وَعَشْرَ مَرَّاتٍ بَعْدَ صَلَاةِ الْمَغْرِبِ فَإِنَّ كُلَّ وَاحِدَةٍ مِنْهُنَّ تُكْتَبُ عَشْرَ حَسَنَاتٍ وَتَحُطُّ عَشْرَ سَيِّئَاتٍ وَكُلُّ وَاحِدَةٍ مِنْهُنَّ كَعِتْقِ رَقَبَةٍ مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏ ‏وَلَا يَحِلُّ لِذَنْبٍ كُسِبَ ذَلِكَ الْيَوْمَ أَنْ يُدْرِكَهُ إِلَّا أَنْ يَكُونَ الشِّرْكُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَهُوَ حَرَسُكِ مَا بَيْنَ أَنْ تَقُولِيهِ ‏ ‏غُدْوَةً ‏ ‏إِلَى أَنْ تَقُولِيهِ عَشِيَّةً مِنْ كُلِّ شَيْطَانٍ وَمِنْ كُلِّ سُوءٍ ‏","","",""],[25341,25341,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى آلِ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُجْنِبُ ثُمَّ يَنَامُ ثُمَّ يَنْتَبِهُ ثُمَّ يَنَامُ ‏","","",""],[25342,25342,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَيْمُونُ بْنُ مُوسَى الْمَرَائِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَرْكَعُ رَكْعَتَيْنِ بَعْدَ ‏ ‏الْوِتْرِ ‏ ‏وَهُوَ جَالِسٌ ‏","","",""],[25343,25343,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ الْحَسَنِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏حَدَّثَتْهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَبَّرَ ‏ ‏لِفَاطِمَةَ ‏ ‏شِبْرًا مِنْ ‏ ‏نِطَاقِهَا ‏","","",""],[25344,25344,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏نَاعِمٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُبْنَى عَلَى الْقَبْرِ أَوْ ‏ ‏يُجَصَّصَ ‏","","",""],[25345,25345,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏نَاعِمٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يُجَصَّصَ ‏ ‏قَبْرٌ أَوْ ‏ ‏يُبْنَى عَلَيْهِ أَوْ يُجْلَسَ عَلَيْهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَيْسَ فِيهِ ‏ ‏أُمُّ سَلَمَةَ ‏","","",""],[25346,25346,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏ ‏عَنْ ‏ ‏أُمِّ حَكِيمٍ السُّلَمِيَّةِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحْرَمَ مِنْ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[25347,25347,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ سُحَيْمٍ ‏ ‏مَوْلَى آلِ ‏ ‏جُبَيْرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي سُفْيَانَ الْأَخْنَسِيِّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أُمِّ حَكِيمٍ ابْنَةِ أُمَيَّةَ بْنِ الْأَخْنَسِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَهَلَّ مِنْ ‏ ‏الْمَسْجِدِ الْأَقْصَى ‏ ‏بِعُمْرَةٍ ‏ ‏أَوْ بِحَجَّةٍ ‏ ‏غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏قَالَ ‏ ‏فَرَكِبَتْ ‏ ‏أُمُّ حَكِيمٍ ‏ ‏عِنْدَ ذَلِكَ الْحَدِيثِ إِلَى ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏حَتَّى ‏ ‏أَهَلَّتْ ‏ ‏مِنْهُ بِعُمْرَةٍ ‏","","",""],[25348,25348,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لِأَزْوَاجِهِ ‏ ‏إِنَّ الَّذِي ‏ ‏يَحْنُو عَلَيْكُنَّ بَعْدِي لَهُوَ الصَّادِقُ الْبَارُّ اللَّهُمَّ اسْقِ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏مِنْ سَلْسَبِيلِ الْجَنَّةِ ‏","","",""],[25349,25349,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ مَوْهَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏يَعْنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏قَالَ ‏ ‏أَجْمَعَ أَبِي عَلَى الْعُمْرَةِ فَلَمَّا حَضَرَ خُرُوجُهُ قَالَ أَيْ بُنَيَّ لَوْ دَخَلْنَا عَلَى الْأَمِيرِ فَوَدَّعْنَاهُ قُلْتُ مَا شِئْتَ قَالَ فَدَخَلْنَا عَلَى ‏ ‏مَرْوَانَ ‏ ‏وَعِنْدَهُ نَفَرٌ فِيهِمْ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏فَذَكَرُوا الرَّكْعَتَيْنِ الَّتِي يُصَلِّيهِمَا ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏بَعْدَ الْعَصْرِ فَقَالَ لَهُ ‏ ‏مَرْوَانُ ‏ ‏مِمَّنْ أَخَذْتَهُمَا يَا ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَنِي بِهِمَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فَأَرْسَلَ ‏ ‏مَرْوَانُ ‏ ‏إِلَى ‏ ‏عَائِشَةَ ‏ ‏مَا رَكْعَتَانِ يَذْكُرُهُمَا ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ عَنْكِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُصَلِّيهِمَا بَعْدَ الْعَصْرِ فَأَرْسَلَتْ إِلَيْهِ أَخْبَرَتْنِي ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَأَرْسَلَ إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏مَا رَكْعَتَانِ زَعَمَتْ ‏ ‏عَائِشَةُ ‏ ‏أَنَّكِ ‏ ‏أَخْبَرْتِيهَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُصَلِّيهِمَا بَعْدَ الْعَصْرِ فَقَالَتْ يَغْفِرُ اللَّهُ ‏ ‏لِعَائِشَةَ ‏ ‏لَقَدْ وَضَعَتْ أَمْرِي عَلَى غَيْرِ مَوْضِعِهِ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ وَقَدْ أُتِيَ بِمَالٍ فَقَعَدَ يَقْسِمُهُ حَتَّى أَتَاهُ الْمُؤَذِّنُ بِالْعَصْرِ ‏ ‏فَصَلَّى الْعَصْرَ ثُمَّ انْصَرَفَ إِلَيَّ وَكَانَ يَوْمِي فَرَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ فَقُلْتُ ‏ ‏مَا هَاتَانِ الرَّكْعَتَانِ يَا رَسُولَ اللَّهِ أُمِرْتَ بِهِمَا قَالَ لَا وَلَكِنَّهُمَا رَكْعَتَانِ كُنْتُ أَرْكَعُهُمَا بَعْدَ الظُّهْرِ فَشَغَلَنِي قَسْمُ هَذَا الْمَالِ حَتَّى جَاءَنِي الْمُؤَذِّنُ بِالْعَصْرِ فَكَرِهْتُ أَنْ أَدَعَهُمَا فَقَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏اللَّهُ أَكْبَرُ أَلَيْسَ قَدْ صَلَّاهُمَا مَرَّةً وَاحِدَةً وَاللَّهِ لَا أَدَعُهُمَا أَبَدًا وَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏مَا رَأَيْتُهُ صَلَّاهُمَا قَبْلَهَا وَلَا بَعْدَهَا ‏","","",""],[25350,25350,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ يَعْنِي زُهَيْرَ بْنَ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏عَنْ ‏ ‏مُسَّةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ النُّفَسَاءُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقْعُدُ بَعْدَ نِفَاسِهَا أَرْبَعِينَ يَوْمًا ‏ ‏أَوْ أَرْبَعِينَ لَيْلَةً شَكَّ ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏وَكُنَّا ‏ ‏نَطْلِي عَلَى وُجُوهِنَا ‏ ‏الْوَرْسَ ‏ ‏مِنْ ‏ ‏الْكَلَفِ ‏","","",""],[25351,25351,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَامَ شَهْرَيْنِ مُتَتَابِعَيْنِ إِلَّا أَنَّهُ كَانَ ‏ ‏يَصِلُ شَعْبَانَ بِرَمَضَانَ ‏","","",""],[25352,25352,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏أَوْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ حَدَّثَتْنَا ‏ ‏أُمُّنَا ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَمَّارٍ ‏ ‏تَقْتُلُكَ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏","","",""],[25353,25353,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ مَمْلَكٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ وَقِرَاءَتِهِ قَالَتْ مَا لَكُمْ وَلِصَلَاتِهِ وَلِقِرَاءَتِهِ قَدْ كَانَ ‏ ‏يُصَلِّي قَدْرَ مَا يَنَامُ وَيَنَامُ قَدْرَ مَا ‏ ‏يُصَلِّي وَإِذَا هِيَ ‏ ‏تَنْعَتُ ‏ ‏قِرَاءَتَهُ فَإِذَا قِرَاءَةٌ مُفَسَّرَةٌ حَرْفًا حَرْفًا ‏","","",""],[25354,25354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ عَبْدِ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏أُمِّ مُوسَى ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏وَالَّذِي أَحْلِفُ بِهِ إِنْ كَانَ ‏ ‏عَلِيٌّ ‏ ‏لَأَقْرَبَ النَّاسِ ‏ ‏عَهْدًا ‏ ‏بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏عُدْنَا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَدَاةً ‏ ‏بَعْدَ ‏ ‏غَدَاةٍ ‏ ‏يَقُولُ جَاءَ ‏ ‏عَلِيٌّ ‏ ‏مِرَارًا قَالَتْ وَأَظُنُّهُ كَانَ بَعَثَهُ فِي حَاجَةٍ قَالَتْ فَجَاءَ بَعْدُ فَظَنَنْتُ أَنَّ لَهُ إِلَيْهِ حَاجَةً فَخَرَجْنَا مِنْ الْبَيْتِ فَقَعَدْنَا عِنْدَ الْبَابِ فَكُنْتُ مِنْ ‏ ‏أَدْنَاهُمْ ‏ ‏إِلَى الْبَابِ ‏ ‏فَأَكَبَّ ‏ ‏عَلَيْهِ ‏ ‏عَلِيٌّ ‏ ‏فَجَعَلَ يُسَارُّهُ ‏ ‏وَيُنَاجِيهِ ثُمَّ ‏ ‏قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ يَوْمِهِ ذَلِكَ فَكَانَ أَقْرَبَ النَّاسِ بِهِ ‏ ‏عَهْدًا ‏","","",""],[25355,25355,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ سَمِعْنَا ‏ ‏مِنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ بِنْتَ أُمِّ سَلَمَةَ ‏ ‏حَدَّثَتْهُ قَالَتْ حَدَّثَتْنِي ‏ ‏أُمِّي ‏ ‏قَالَتْ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْخَمِيلَةِ ‏ ‏فَحِضْتُ ‏ ‏فَانْسَلَلْتُ ‏ ‏مِنْ ‏ ‏الْخَمِيلَةِ ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنُفِسْتِ فَقُلْتُ نَعَمْ فَلَبِسْتُ ثِيَابَ حَيْضَتِي فَدَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُ فِي ‏ ‏الْخَمِيلَةِ ‏ ‏قَالَتْ وَكُنْتُ أَغْتَسِلُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ قَالَتْ وَكَانَ يُقَبِّلُ وَهُوَ صَائِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏بِنَحْوِهِ فِي هَذَا الْإِسْنَادِ إِلَّا أَنَّهُ قَالَ مِنْ إِنَاءٍ وَاحِدٍ مِنْ الْجَنَابَةِ ‏","","",""],[25356,25356,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي يَشْرَبُ فِي إِنَاءٍ مِنْ فِضَّةٍ إِنَّمَا ‏ ‏يُجَرْجِرُ ‏ ‏فِي بَطْنِهِ نَارَ جَهَنَّمَ ‏","","",""],[25357,25357,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ الْأَشْيَبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَرَّاجٌ ‏ ‏عَنِ ‏ ‏السَّائِبِ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ نِسْوَةً دَخَلْنَ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏مِنْ أَهْلِ ‏ ‏حِمْصَ ‏ ‏فَسَأَلَتْهُنَّ مِمَّنْ أَنْتُنَّ قُلْنَ مِنْ أَهْلِ ‏ ‏حِمْصَ ‏ ‏فَقَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا امْرَأَةٍ نَزَعَتْ ثِيَابَهَا فِي غَيْرِ بَيْتِهَا خَرَقَ اللَّهُ عَنْهَا سِتْرًا ‏","","",""],[25358,25358,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَرَّاجٌ ‏ ‏عَنِ ‏ ‏السَّائِبِ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَ عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ صَلَاةِ النِّسَاءِ فِي ‏ ‏قَعْرِ ‏ ‏بُيُوتِهِنَّ ‏","","",""],[25359,25359,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُسْلِمٍ الْجُنْدُعِيِّ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏ابْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏و قَالَ ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو يَعْنِي ابْنَ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُسْلِمِ بْنِ عُمَارَةَ بْنِ أُكَيْمَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنْ كَانَ قَالَهُ كَذَا قَالَ أَبِي فِي الْحَدِيثِ ‏ ‏مَنْ أَرَادَ أَنْ ‏ ‏يُضَحِّيَ ‏ ‏فَلَا ‏ ‏يُقَلِّمْ ‏ ‏أَظْفَارًا وَلَا يَحْلِقْ شَيْئًا مِنْ شَعْرِهِ فِي ‏ ‏الْعَشْرِ ‏ ‏الْأُوَلِ مِنْ ذِي الْحِجَّةِ ‏","","",""],[25360,25360,"","","‏ ‏حَدَّثَنَا ‏ ‏طَلْقُ بْنُ غَنَّامِ بْنِ طَلْقٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُثْمَانَ الْوَرَّاقُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَدَخَلَ عَلَيْهَا ابْنُ أَخٍ لَهَا فَصَلَّى فِي بَيْتِهَا رَكْعَتَيْنِ فَلَمَّا سَجَدَ نَفَخَ التُّرَابَ فَقَالَتْ لَهُ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏ابْنَ أَخِي لَا تَنْفُخْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لِغُلَامٍ لَهُ يُقَالُ لَهُ ‏ ‏يَسَارٌ ‏ ‏وَنَفَخَ ‏ ‏تَرِّبْ وَجْهَكَ لِلَّهِ ‏","","",""],[25361,25361,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏أَكْثَرُ مَا عَلِمْتُ أُتِيَ بِهِ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْمَالِ بِخَرِيطَةٍ فِيهَا ثَمَانِ مِائَةِ دِرْهَمٍ ‏","","",""],[25362,25362,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَوْفٍ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏قَالَ حَدَّثَتْنَا ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي فَجَاءَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَا ‏ ‏صَدَقَةُ ‏ ‏كَذَا وَكَذَا قَالَ كَذَا وَكَذَا قَالَ فَإِنَّ فُلَانًا تَعَدَّى عَلَيَّ قَالَ فَنَظَرُوهُ فَوَجَدُوهُ قَدْ تَعَدَّى عَلَيْهِ ‏ ‏بِصَاعٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَيْفَ بِكُمْ إِذَا سَعَى مَنْ يَتَعَدَّى عَلَيْكُمْ أَشَدَّ مِنْ هَذَا التَّعَدِّي ‏","","",""],[25363,25363,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ شَيْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَنَا لَا نُذْكَرُ فِي الْقُرْآنِ كَمَا يُذْكَرُ الرِّجَالُ قَالَتْ فَلَمْ ‏ ‏يَرُعْنِي ‏ ‏مِنْهُ يَوْمًا إِلَّا وَنِدَاؤُهُ عَلَى الْمِنْبَرِ يَا أَيُّهَا النَّاسُ قَالَتْ وَأَنَا أُسَرِّحُ رَأْسِي فَلَفَفْتُ شَعْرِي ثُمَّ ‏ ‏دَنَوْتُ ‏ ‏مِنْ الْبَابِ فَجَعَلْتُ سَمْعِي عِنْدَ ‏ ‏الْجَرِيدِ ‏ ‏فَسَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ { ‏إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ‏} ‏هَذِهِ الْآيَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ { ‏أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا ‏}","","",""],[25364,25364,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُكْثِرُ فِي دُعَائِهِ أَنْ يَقُولَ ‏ ‏اللَّهُمَّ مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَوَإِنَّ الْقُلُوبَ لَتَتَقَلَّبُ قَالَ نَعَمْ مَا مِنْ خَلْقِ اللَّهِ مِنْ بَنِي ‏ ‏آدَمَ ‏ ‏مِنْ بَشَرٍ إِلَّا أَنَّ قَلْبَهُ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ فَإِنْ شَاءَ اللَّهُ عَزَّ وَجَلَّ أَقَامَهُ وَإِنْ شَاءَ اللَّهُ أَزَاغَهُ فَنَسْأَلُ اللَّهَ رَبَّنَا أَنْ لَا يُزِيغَ قُلُوبَنَا بَعْدَ إِذْ هَدَانَا وَنَسْأَلُهُ أَنْ ‏ ‏يَهَبَ ‏ ‏لَنَا مِنْ لَدُنْهُ رَحْمَةً إِنَّهُ هُوَ الْوَهَّابُ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَلَا تُعَلِّمُنِي دَعْوَةً أَدْعُو بِهَا لِنَفْسِي قَالَ بَلَى قُولِي ‏ ‏اللَّهُمَّ رَبَّ ‏ ‏مُحَمَّدٍ ‏ ‏النَّبِيِّ اغْفِرْ لِي ذَنْبِي وَأَذْهِبْ غَيْظَ قَلْبِي وَأَجِرْنِي مِنْ مُضِلَّاتِ الْفِتَنِ مَا أَحْيَيْتَنَا ‏","","",""],[25365,25365,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ضَبَّةَ بْنِ مُحْصِنٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهَا سَتَكُونُ أُمَرَاءُ تَعْرِفُونَ وَتُنْكِرُونَ فَمَنْ أَنْكَرَ سَلِمَ وَمَنْ كَرِهَ بَرِئَ وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ فَقَالَ أَلَا نَقْتُلُهُمْ فَقَالَ لَا مَا صَلَّوْا ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏فَمَنْ عَرَفَ بَرِئَ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏أَلَا نَقْتُلُهُمْ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّهَا سَتَكُونُ ‏","","",""],[25366,25366,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏بَعْضِ وَلَدِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[25367,25367,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ الْمُهَلَّبِيُّ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهَا ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ ‏ ‏هَلْ عَلَى الْمَرْأَةِ غُسْلٌ إِذَا احْتَلَمَتْ قَالَ نَعَمْ إِذَا رَأَتْ الْمَاءَ ‏","","",""],[25368,25368,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَزْوَاجِهِ ‏ ‏إِنَّ الَّذِي ‏ ‏يَحْنُو عَلَيْكُنَّ مِنْ بَعْدِي لَهُوَ الصَّادِقُ الْبَارُّ اللَّهُمَّ اسْقِ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏مِنْ سَلْسَبِيلِ الْجَنَّةِ ‏","","",""],[25369,25369,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُدَيْلٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمُتَوَفَّى عَنْهَا زَوْجُهَا لَا تَلْبَسُ ‏ ‏الْمُعَصْفَرَةَ ‏ ‏مِنْ الثِّيَابِ وَلَا ‏ ‏الْمُمَشَّقَةَ ‏ ‏وَلَا الْحُلِيَّ وَلَا ‏ ‏تَخْتَضِبُ ‏ ‏وَلَا تَكْتَحِلُ ‏","","",""],[25370,25370,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏وَعَبْدِ الرَّحْمَنِ يَعْنِي السَّرَّاجَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَرِبَ فِي إِنَاءٍ مِنْ فِضَّةٍ فَإِنَّمَا ‏ ‏يُجَرْجِرُ ‏ ‏فِي بَطْنِهِ نَارَ جَهَنَّمَ ‏","","",""],[25371,25371,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا ‏ ‏سُئِلَتْ عَنْ قِرَاءَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ كَانَ ‏ ‏يُقَطِّعُ قِرَاءَتَهُ آيَةً آيَةً ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏} { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} { ‏الرَّحْمَنِ الرَّحِيمِ ‏} { ‏مَالِكِ يَوْمِ الدِّينِ ‏}","","",""],[25372,25372,"","","‏ ‏حَدَّثَنَا ‏ ‏شُجَاعُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏عَنْ ‏ ‏مُسَّةَ الْأَزْدِيَّةِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏النُّفَسَاءُ ‏ ‏تَجْلِسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعِينَ يَوْمًا وَكُنَّا نَطْلِي وُجُوهَنَا ‏ ‏بِالْوَرْسِ ‏ ‏مِنْ ‏ ‏الْكَلَفِ ‏","","",""],[25373,25373,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجُّ جِهَادُ كُلِّ ضَعِيفٍ ‏","","",""],[25374,25374,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏سَأَلْتُهُ عَنْ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ فَقَالَ دَخَلْتُ أَنَا ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏عَلَى ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏لَقَدْ ذَكَرْتَ رَكْعَتَيْنِ بَعْدَ الْعَصْرِ وَقَدْ بَلَغَنِي أَنَّ أُنَاسًا يُصَلُّونَهَا وَلَمْ نَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّاهُمَا وَلَا أَمَرَ بِهِمَا قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏ذَاكَ مَا يَقْضِي النَّاسَ بِهِ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏قَالَ فَجَاءَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَقَالَ مَا رَكْعَتَانِ قَضَى بِهِمَا النَّاسُ فَقَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَرْسَلَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏رَجُلَيْنِ أَنَّ أَمِيرَ الْمُؤْمِنِينَ يَقْرَأُ عَلَيْكِ السَّلَامَ وَيَقُولُ ‏ ‏مَا رَكْعَتَانِ زَعَمَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏أَنَّكِ ‏ ‏أَمَرْتِيهِ بِهِمَا بَعْدَ الْعَصْرِ قَالَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏ذَاكَ مَا أَخْبَرَتْهُ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قَالَ فَدَخَلْنَا عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَأَخْبَرْنَاهَا مَا قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقَالَتْ يَرْحَمُهَا اللَّهُ أَوَلَمْ أُخْبِرْهَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نَهَى عَنْهُمَا ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عُبَيْدَةَ بْنُ عَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ ‏ ‏وَعَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ لَيْلَتِي الَّتِي يَصِيرُ إِلَيَّ فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏ابْنِ أَبِي عَدِيٍّ ‏ ‏قَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏أَوَلَا يَشُدُّ لَكَ هَذَا الْأَثَرُ ‏ ‏إِفَاضَةَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ يَوْمِهِ ذَلِكَ قَبْلَ أَنْ يُمْسِيَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ رُومَانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏مَوْلَى ‏ ‏الزُّبَيْرِ بْنِ نَوْفَلٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏زَيْنَبُ ابْنَةُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهَا ‏ ‏أُمِّ سَلَمَةَ ‏ ‏هَذَا الْحَدِيثَ ‏","","",""],[25375,25375,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ رَافِعٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَمِعْتُهَا تَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا حَضَرَتْ الصَّلَاةُ وَحَضَرَ الْعَشَاءُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[25376,25376,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏فَزَعَمَ ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏أَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضُبَاعَةَ بِنْتَ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏وَهِيَ ‏ ‏شَاكِيَةٌ ‏ ‏فَقَالَ أَلَا تَخْرُجِينَ مَعَنَا فِي سَفَرِنَا هَذَا وَهُوَ يُرِيدُ حَجَّةَ الْوَدَاعِ قَالَتْ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏شَاكِيَةٌ ‏ ‏وَأَخْشَى أَنْ ‏ ‏تَحْبِسَنِي ‏ ‏شَكْوَايَ ‏ ‏قَالَ ‏ ‏فَأَهِلِّي ‏ ‏بِالْحَجِّ وَقُولِي ‏ ‏اللَّهُمَّ مَحِلِّي حَيْثُ ‏ ‏تَحْبِسُنِي ‏","","",""],[25377,25377,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏رَبَّنَا اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي لِلطَّرِيقِ الْأَقْوَمِ ‏","","",""],[25378,25378,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْحَسَنِ الْأَحْوَلُ يَعْنِي عَلِيَّ بْنَ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏عَنْ ‏ ‏مُسَّةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏النُّفَسَاءُ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقْعُدُ بَعْدَ ‏ ‏نِفَاسِهَا ‏ ‏أَرْبَعِينَ يَوْمًا ‏ ‏أَوْ أَرْبَعِينَ لَيْلَةً ‏ ‏وَكُنَّا نَطْلِي عَلَى وُجُوهِنَا ‏ ‏الْوَرْسَ ‏ ‏مِنْ ‏ ‏الْكَلَفِ ‏","","",""],[25379,25379,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏فَاطِمَةُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنِّي ‏ ‏أُسْتَحَاضُ ‏ ‏فَقَالَ لَيْسَ ذَلِكَ بِالْحَيْضِ ‏ ‏إِنَّمَا هُوَ ‏ ‏عِرْقٌ ‏ ‏لِتَقْعُدْ أَيَّامَ ‏ ‏أَقْرَائِهَا ‏ ‏ثُمَّ لِتَغْتَسِلْ ثُمَّ ‏ ‏لِتَسْتَثْفِرْ ‏ ‏بِثَوْبٍ وَلْتُصَلِّ ‏","","",""],[25380,25380,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ أَبِي أُمَيَّةَ ‏ ‏أَخِي ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا ثُمَّ يُصْبِحُ صَائِمًا ‏","","",""],[25381,25381,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَهِيَ خَالَتُهُ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ شَرِبَ فِي إِنَاءٍ مِنْ فِضَّةٍ فَإِنَّمَا ‏ ‏يُجَرْجِرُ ‏ ‏فِي بَطْنِهِ نَارَ جَهَنَّمَ ‏","","",""],[25382,25382,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَلَفٌ يَعْنِي ابْنَ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا ظَهَرَتْ الْمَعَاصِي فِي أُمَّتِي عَمَّهُمْ اللَّهُ عَزَّ وَجَلَّ بِعَذَابٍ مِنْ عِنْدِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَمَا فِيهِمْ يَوْمَئِذٍ أُنَاسٌ صَالِحُونَ قَالَ بَلَى قَالَتْ فَكَيْفَ يَصْنَعُ أُولَئِكَ قَالَ يُصِيبُهُمْ مَا أَصَابَ النَّاسَ ثُمَّ يَصِيرُونَ إِلَى مَغْفِرَةٍ مِنْ اللَّهِ وَرِضْوَانٍ ‏","","",""],[25383,25383,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَلَّلَ ‏ ‏عَلَى ‏ ‏عَلِيٍّ ‏ ‏وَحَسَنٍ ‏ ‏وَحُسَيْنٍ ‏ ‏وَفَاطِمَةَ ‏ ‏كِسَاءً ‏ ‏ثُمَّ قَالَ ‏ ‏اللَّهُمَّ هَؤُلَاءِ أَهْلُ بَيْتِي وَخَاصَّتِي اللَّهُمَّ أَذْهِبْ عَنْهُمْ ‏ ‏الرِّجْسَ ‏ ‏وَطَهِّرْهُمْ تَطْهِيرًا فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَنَا مِنْهُمْ قَالَ إِنَّكِ إِلَى خَيْرٍ ‏","","",""],[25384,25384,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ بَعْدَ الظُّهْرِ وَإِنَّهُ جَاءَ وَفْدٌ فَشَغَلُوهُ فَلَمْ يُصَلِّهِمَا فَصَلَّاهُمَا بَعْدَ الْعَصْرِ ‏","","",""],[25385,25385,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏وَالَّذِي تَوَفَّى نَفْسَهُ تَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تُوُفِّيَ حَتَّى كَانَتْ أَكْثَرُ صَلَاتِهِ قَاعِدًا إِلَّا الْمَكْتُوبَةَ وَكَانَ أَعْجَبُ الْعَمَلِ إِلَيْهِ الَّذِي يَدُومُ عَلَيْهِ الْعَبْدُ وَإِنْ كَانَ يَسِيرًا ‏","","",""],[25386,25386,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمُعَدِّلِ عَطِيَّةَ الطُّفَاوِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي إِذْ قَالَتْ الْخَادِمُ إِنَّ ‏ ‏عَلِيًّا ‏ ‏وَفَاطِمَةَ ‏ ‏بِالسُّدَّةِ قَالَ قُومِي عَنْ أَهْلِ بَيْتِي قَالَتْ فَقُمْتُ فَتَنَحَّيْتُ فِي نَاحِيَةِ الْبَيْتِ قَرِيبًا فَدَخَلَ ‏ ‏عَلِيٌّ ‏ ‏وَفَاطِمَةُ ‏ ‏وَمَعَهُمْ ‏ ‏الْحَسَنُ ‏ ‏وَالْحُسَيْنُ ‏ ‏صَبِيَّانِ صَغِيرَانِ فَأَخَذَ الصَّبِيَّيْنِ فَقَبَّلَهُمَا وَوَضَعَهُمَا فِي حِجْرِهِ ‏ ‏وَاعْتَنَقَ ‏ ‏عَلِيًّا ‏ ‏وَفَاطِمَةَ ‏ ‏ثُمَّ ‏ ‏أَغْدَفَ ‏ ‏عَلَيْهِمَا ‏ ‏بِبُرْدَةٍ ‏ ‏لَهُ وَقَالَ ‏ ‏اللَّهُمَّ إِلَيْكَ لَا إِلَى النَّارِ أَنَا وَأَهْلُ بَيْتِي قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ وَأَنَا فَقَالَ وَأَنْتِ ‏","","",""],[25387,25387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَابِطٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏حَفْصَةَ ابْنَةِ عَبْدِ الرَّحْمَنِ ‏ ‏فَقُلْتُ إِنِّي سَائِلُكِ عَنْ أَمْرٍ وَأَنَا أَسْتَحْيِي أَنْ أَسْأَلَكِ عَنْهُ فَقَالَتْ لَا تَسْتَحْيِي يَا ابْنَ أَخِي قَالَ عَنْ ‏ ‏إِتْيَانِ ‏ ‏النِّسَاءِ فِي ‏ ‏أَدْبَارِهِنَّ ‏ ‏قَالَتْ حَدَّثَتْنِي ‏ ‏أُمُّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏الْأَنْصَارَ ‏ ‏كَانُوا لَا يُجِبُّونَ النِّسَاءَ وَكَانَتْ ‏ ‏الْيَهُودُ ‏ ‏تَقُولُ إِنَّهُ مَنْ ‏ ‏جَبَّى ‏ ‏امْرَأَتَهُ كَانَ وَلَدُهُ أَحْوَلَ فَلَمَّا قَدِمَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏الْمَدِينَةَ ‏ ‏نَكَحُوا فِي نِسَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏فَجَبُّوهُنَّ ‏ ‏فَأَبَتْ امْرَأَةٌ أَنْ تُطِيعَ زَوْجَهَا فَقَالَتْ لِزَوْجِهَا لَنْ تَفْعَلَ ذَلِكَ حَتَّى آتِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَتْ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَذَكَرَتْ ذَلِكَ لَهَا فَقَالَتْ اجْلِسِي حَتَّى يَأْتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَحَتْ الْأَنْصَارِيَّةُ أَنْ تَسْأَلَهُ فَخَرَجَتْ فَحَدَّثَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏ادْعِي الْأَنْصَارِيَّةَ فَدُعِيَتْ فَتَلَا عَلَيْهَا هَذِهِ الْآيَةَ ‏ { ‏نِسَاؤُكُمْ ‏ ‏حَرْثٌ ‏ ‏لَكُمْ فَأْتُوا ‏ ‏حَرْثَكُمْ ‏ ‏أَنَّى شِئْتُمْ ‏} ‏صِمَامًا وَاحِدًا ‏","","",""],[25388,25388,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَوْلًى لِأَبِي سَلَمَةَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِذَا صَلَّى الصُّبْحَ حِينَ سَلَّمَ اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا وَاسِعًا وَعَمَلًا مُتَقَبَّلًا ‏","","",""],[25389,25389,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ شَيْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَنَا لَا نُذْكَرُ فِي الْقُرْآنِ كَمَا يُذْكَرُ الرِّجَالُ قَالَتْ فَلَمْ ‏ ‏يَرُعْنِي ‏ ‏مِنْهُ يَوْمَئِذٍ إِلَّا وَنِدَاؤُهُ عَلَى الْمِنْبَرِ قَالَتْ وَأَنَا أُسَرِّحُ شَعْرِي فَلَفَفْتُ شَعْرِي ثُمَّ خَرَجْتُ إِلَى حُجْرَةٍ مِنْ حُجَرِ بَيْتِي فَجَعَلْتُ سَمْعِي عِنْدَ ‏ ‏الْجَرِيدِ ‏ ‏فَإِذَا هُوَ يَقُولُ عِنْدَ الْمِنْبَرِ يَا أَيُّهَا النَّاسُ إِنَّ اللَّهَ يَقُولُ فِي كِتَابِهِ ‏ { ‏إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ‏ ‏إِلَى آخِرِ الْآيَةِ ‏ ‏أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا ‏} ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[25390,25390,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ وَالَّذِي تَوَفَّى نَفْسَهُ ‏ ‏مَا مَاتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى كَانَتْ أَكْثَرُ صَلَاتِهِ قَاعِدًا إِلَّا الصَّلَاةَ الْمَكْتُوبَةَ وَكَانَ أَحَبُّ الْعَمَلِ إِلَيْهِ الَّذِي يَدُومُ عَلَيْهِ الْعَبْدُ وَإِنْ كَانَ يَسِيرًا ‏","","",""],[25391,25391,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏ضَبَّةَ بْنِ مُحْصِنٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيَكُونُ أُمَرَاءُ تَعْرِفُونَ وَتُنْكِرُونَ فَمَنْ أَنْكَرَ فَقَدْ بَرِئَ وَمَنْ كَرِهَ فَقَدْ سَلِمَ وَلَكِنْ مَنْ رَغِبَ وَتَابَعَ قَالُوا يَا رَسُولَ اللَّهِ أَلَا نُقَاتِلُهُمْ قَالَ لَا مَا صَلَّوْا الصَّلَاةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ الْحَدَّادُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ضَبَّةَ بْنِ مُحْصِنٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[25392,25392,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَقِيقٌ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا حَضَرْتُمْ الْمَرِيضَ ‏ ‏أَوْ الْمَيِّتَ ‏ ‏فَقُولُوا خَيْرًا فَإِنَّ الْمَلَائِكَةَ تُؤَمِّنُ عَلَى مَا تَقُولُونَ قَالَتْ فَلَمَّا مَاتَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَقُولُ قَالَ قُولِي ‏ ‏اللَّهُمَّ اغْفِرْ لَنَا وَلَهُ ‏ ‏وَأَعْقِبْنِي ‏ ‏مِنْهُ ‏ ‏عُقْبَى ‏ ‏حَسَنَةً ‏ ‏وَقَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏صَالِحَةً ‏ ‏قَالَتْ ‏ ‏فَأَعْقَبَنِي ‏ ‏اللَّهُ عَزَّ وَجَلَّ مِنْهُ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25393,25393,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏أَخِي ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُصْبِحُ جُنُبًا فَيَغْتَسِلُ وَيَصُومُ ‏ ‏قَالَ ‏ ‏فَرَدَّ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فُتْيَاهُ ‏","","",""],[25394,25394,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَوَكِيعٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تَقُولُ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمَسُّ ‏ ‏أَهْلَهُ مِنْ اللَّيْلِ فَيُصْبِحُ جُنُبًا مِنْ غَيْرِ احْتِلَامٍ فَيَغْتَسِلُ وَيَصُومُ ‏","","",""],[25395,25395,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي يَشْرَبُ فِي آنِيَةِ الْفِضَّةِ إِنَّمَا ‏ ‏يُجَرْجِرُ ‏ ‏فِي بَطْنِهِ نَارَ جَهَنَّمَ ‏","","",""],[25396,25396,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوْنٍ مُحَمَّدُ بْنُ عُبَيْدِ اللَّهِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏مَرْوَانَ ‏ ‏قَالَ تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ قَالَ فَأَرْسَلَ ‏ ‏مَرْوَانُ ‏ ‏إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَسَأَلَهَا فَقَالَتْ ‏ ‏نَهَسَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدِي كَتِفًا ثُمَّ خَرَجَ إِلَى الصَّلَاةِ وَلَمْ يَمَسَّ مَاءً ‏ ‏و قَالَ ‏ ‏أَبِي ‏ ‏لَمْ يَسْمَعْ ‏ ‏سُفْيَانُ ‏ ‏مِنْ ‏ ‏أَبِي عَوْنٍ ‏ ‏إِلَّا هَذَا الْحَدِيثَ ‏","","",""],[25397,25397,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَتْهُ عَنْ الْمَرْأَةِ ‏ ‏تَرَى فِي مَنَامِهَا مَا يَرَى الرَّجُلُ فَقَالَ ‏ ‏إِذَا رَأَتْ الْمَاءَ فَلْتَغْتَسِلْ قَالَتْ قُلْتُ فَضَحْتِ النِّسَاءَ وَهَلْ تَحْتَلِمُ الْمَرْأَةُ فَقَال النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرِبَتْ ‏ ‏يَمِينُكِ فَبِمَ يُشْبِهُهَا وَلَدُهَا إِذًا ‏","","",""],[25398,25398,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏طَلْحَةُ بْنُ يَحْيَى ‏ ‏سَمِعْتُهُ مِنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏شُغِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّكْعَتَيْنِ بَعْدَ الظُّهْرِ فَصَلَّاهُمَا بَعْدَ الْعَصْرِ ‏","","",""],[25399,25399,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏وَهْبٍ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَهِيَ ‏ ‏تَخْتَمِرُ ‏ ‏فَقَالَ ‏ ‏لَيَّةً ‏ ‏لَا ‏ ‏لَيَّتَيْنِ ‏","","",""],[25400,25400,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا خَرَجَ مِنْ بَيْتِهِ قَالَ ‏ ‏بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ أَنْ نَزِلَّ أَوْ نَضِلَّ أَوْ نَظْلِمَ أَوْ نُظْلَمَ أَوْ نَجْهَلَ أَوْ يُجْهَلَ عَلَيْنَا ‏","","",""]];
